import { useEffect, useRef, useState } from 'react'
import { useMutation, useQueries, useQuery, useQueryClient } from '@tanstack/react-query'
import { Link, NavLink, Navigate, Route, Routes, useSearchParams } from 'react-router-dom'
import { api, authToken, type AppUser, type Field, type Issue, type LiveDataModel, type LiveIssueMetadata, type Project, type ProjectPlan, type UserPayload, type WbsFlow } from './api'
import './metrics.css'
import './projectPlan.css'
import './dataModel.css'
import './dataModelWide.css'

function Toggle({checked, label, onChange}: {checked: boolean; label: string; onChange: (value: boolean) => void}) {
  return <label className="toggle"><input type="checkbox" checked={checked} onChange={e => onChange(e.target.checked)} /><span aria-hidden="true" /> <span className="sr-only">{label}</span></label>
}

export default function App() {
  const [token, setToken] = useState(authToken.get())
  const [fontSize, setFontSize] = useState(() => localStorage.getItem('portfolio_font_size') ?? 'default')
  const [fontMenuOpen, setFontMenuOpen] = useState(false)
  const me = useQuery({queryKey: ['current-user', token], queryFn: api.me, enabled: Boolean(token), retry: false})
  useEffect(() => { if (me.isError) { authToken.clear(); setToken(null) } }, [me.isError])
  useEffect(() => { document.documentElement.dataset.fontSize = fontSize; localStorage.setItem('portfolio_font_size', fontSize) }, [fontSize])
  const content = !token ? <LoginScreen onLogin={(sessionToken) => { authToken.set(sessionToken); setToken(sessionToken) }}/> : me.isLoading || !me.data ? <div className="auth-loading"><span/><strong>Loading Portfolio Intelligence…</strong></div> : <WorkspaceApp user={me.data} onLogout={async () => { try { await api.logout() } finally { authToken.clear(); setToken(null) } }}/>
  return <>{content}<FontSizeControl value={fontSize} open={fontMenuOpen} onToggle={() => setFontMenuOpen(value => !value)} onChange={value => { setFontSize(value); setFontMenuOpen(false) }}/></>
}

function FontSizeControl({value, open, onToggle, onChange}: {value: string; open: boolean; onToggle: () => void; onChange: (value: string) => void}) {
  const options = [{id: 'default', label: 'Default', sample: 'A'}, {id: 'comfortable', label: 'Comfortable', sample: 'A+'}, {id: 'large', label: 'Large', sample: 'A++'}]
  return <div className="font-size-control"><button className="font-size-trigger" onClick={onToggle} aria-expanded={open} aria-label="Change application font size"><span>Aa</span><i aria-hidden="true">{open ? '×' : '⌃'}</i></button>{open && <section className="font-size-menu" aria-label="Font size options"><div><strong>Text size</strong><small>Applies across the application</small></div>{options.map(option => <button className={value === option.id ? 'selected' : ''} onClick={() => onChange(option.id)} key={option.id}><b>{option.sample}</b><span>{option.label}</span>{value === option.id && <i aria-hidden="true">✓</i>}</button>)}</section>}</div>
}

function LoginScreen({onLogin}: {onLogin: (token: string) => void}) {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const login = useMutation({mutationFn: () => api.login(username, password), onSuccess: data => onLogin(data.token)})
  const submit = (event: React.FormEvent) => { event.preventDefault(); login.mutate() }
  return <main className="login-page"><section className="login-visual"><div className="login-brand"><img src="https://www.jswsteel.in/wp-content/themes/JSWSteel/images/JSW_Steel_Logo.svg" alt="JSW Steel"/><span>Portfolio Intelligence</span></div><div className="login-copy"><p>EXECUTIVE PORTFOLIO INTELLIGENCE</p><h1>Clarity across every project.</h1><span>Secure, role-based access to Jira portfolio traceability, execution, and governance views.</span><strong className="login-credit">Designed and Developed by VJNR MES Team</strong></div><div className="login-art" aria-hidden="true"><i/><i/><i/><i/></div></section><section className="login-panel"><form className="login-card" onSubmit={submit}><div><span className="step">WELCOME BACK</span><h2>Sign in</h2><p>Use your locally managed Portfolio Intelligence account.</p></div><label>Username<input autoFocus autoComplete="username" value={username} onChange={event => setUsername(event.target.value)} placeholder="Enter username"/></label><label>Password<input type="password" autoComplete="current-password" value={password} onChange={event => setPassword(event.target.value)} placeholder="Enter password"/></label>{login.error && <p className="login-error" role="alert">{login.error.message}</p>}<button disabled={!username || !password || login.isPending}>{login.isPending ? 'Signing in…' : 'Sign in'}</button><small>Authorized users only · Credentials are stored locally and passwords are hashed.</small></form></section></main>
}

function ScreenGate({allowed, children}: {allowed: boolean; children: React.ReactNode}) {
  return allowed ? children : <Navigate to="/access-denied" replace/>
}

function WorkspaceApp({user, onLogout}: {user: AppUser; onLogout: () => void}) {
  const queryClient = useQueryClient()
  const [notice, setNotice] = useState('')
  const [configurationOpen, setConfigurationOpen] = useState(false)
  const [portfolioSyncOpen, setPortfolioSyncOpen] = useState(false)
  const [portfolioViewOpen, setPortfolioViewOpen] = useState(false)
  const [appSettingOpen, setAppSettingOpen] = useState(false)
  const [executionViewOpen, setExecutionViewOpen] = useState(false)
  const [gridConfigOpen, setGridConfigOpen] = useState(false)
  const [viewConfigOpen, setViewConfigOpen] = useState(false)
  const [maintenanceOpen, setMaintenanceOpen] = useState(false)
  const [documentationOpen, setDocumentationOpen] = useState(false)
  const [portfolioIntelligenceOpen, setPortfolioIntelligenceOpen] = useState(false)
  const [projectPortfolioOpen, setProjectPortfolioOpen] = useState(false)
  const health = useQuery({queryKey: ['health'], queryFn: api.health})
  const projects = useQuery({queryKey: ['projects'], queryFn: api.projects})
  const activeProjects = projects.data?.items.filter(project => project.active) ?? []
  const fields = useQuery({queryKey: ['fields'], queryFn: () => api.fields()})
  const syncStatus = useQuery({queryKey: ['sync-status'], queryFn: api.syncStatus, refetchInterval: 15_000})
  const anomalies = useQuery({queryKey: ['anomalies'], queryFn: api.anomalies})
  const summary = useQuery({queryKey: ['summary', activeProjects.map(project => project.jira_project_id)], queryFn: () => api.summary(activeProjects.map(project => project.jira_project_id)), enabled: activeProjects.length > 0})
  const statusGroups = useQuery({queryKey: ['status-groups', activeProjects.map(project => project.jira_project_id)], queryFn: () => api.groupBy('status_id', activeProjects.map(project => project.jira_project_id)), enabled: activeProjects.length > 0})
  const test = useMutation({mutationFn: api.testConnection, onSuccess: data => setNotice(`Connected as ${data.account.display_name ?? data.account.account_id ?? 'Jira user'}.`), onError: e => setNotice(e.message)})
  const refresh = useMutation({mutationFn: api.refresh, onSuccess: data => {setNotice(`Metadata refreshed: ${data.counts.projects ?? 0} projects and ${data.counts.fields ?? 0} fields.`); queryClient.invalidateQueries()}, onError: e => setNotice(e.message)})
  const projectSelect = useMutation({mutationFn: ({id, selected}: {id: string; selected: boolean}) => api.selectProject(id, selected), onSuccess: () => queryClient.invalidateQueries({queryKey: ['projects']})})
  const sync = useMutation({mutationFn: api.sync, onSuccess: data => {setNotice(`Sync completed: ${data.fetched_count} issues, ${data.anomaly_count} hierarchy anomalies.`); queryClient.invalidateQueries()}, onError: e => setNotice(e.message)})
  const busy = test.isPending || refresh.isPending || sync.isPending
  const can = (screen: string) => user.role === 'admin' || user.screen_permissions.includes(screen)
  const homePath = can('overview') ? '/overview' : can('hierarchy') ? '/hierarchy' : can('traceability') ? '/cards' : can('wbs') ? '/wbs' : can('sprints') ? '/sprints' : can('documentation') ? '/documentation/configuration' : '/access-denied'

  const projectIds = activeProjects.map(project => project.jira_project_id)
  const projectLabel = activeProjects.length === 1 ? `${activeProjects[0].key} · Jira ID ${activeProjects[0].jira_project_id}` : `${activeProjects.length} active projects`

  return <div className="shell">
    <aside><div className="brand"><img className="brand-logo" src="https://www.jswsteel.in/wp-content/themes/JSWSteel/images/JSW_Steel_Logo.svg" alt="JSW Steel"/><div>Portfolio<br/><strong>Intelligence</strong></div></div><nav>
      {can('overview') && <div className="nav-group"><button className="nav-parent" onClick={() => setPortfolioIntelligenceOpen(value => !value)} aria-expanded={portfolioIntelligenceOpen}><span className="nav-title"><i aria-hidden="true">▥</i>Portfolio Intelligence</span><i aria-hidden="true">{portfolioIntelligenceOpen ? '−' : '+'}</i></button>{portfolioIntelligenceOpen && <div className="nav-children"><NavLink to="/overview">Overview</NavLink><NavLink to="/portfolio-metrics">Portfolio Metrics</NavLink></div>}</div>}
      {user.role === 'admin' && <div className="nav-group"><button className="nav-parent" onClick={() => setProjectPortfolioOpen(value => !value)} aria-expanded={projectPortfolioOpen}><span className="nav-title"><i aria-hidden="true">◇</i>Project Portfolio</span><i aria-hidden="true">{projectPortfolioOpen ? '−' : '+'}</i></button>{projectPortfolioOpen && <div className="nav-children"><NavLink to="/project-plan">Project Plan</NavLink></div>}</div>}
      {(can('hierarchy') || can('traceability') || can('wbs')) && <div className="nav-group"><button className="nav-parent" onClick={() => setPortfolioViewOpen(value => !value)} aria-expanded={portfolioViewOpen}><span className="nav-title"><i aria-hidden="true">⌘</i>Portfolio View</span><i aria-hidden="true">{portfolioViewOpen ? '−' : '+'}</i></button>{portfolioViewOpen && <div className="nav-children">{can('hierarchy') && <NavLink to="/hierarchy">Hierarchy</NavLink>}{can('traceability') && <NavLink to="/cards">Traceability</NavLink>}{can('wbs') && <NavLink to="/wbs">WBS view</NavLink>}</div>}</div>}
      {can('sprints') && <div className="nav-group"><button className="nav-parent" onClick={() => setExecutionViewOpen(value => !value)} aria-expanded={executionViewOpen}><span className="nav-title"><i aria-hidden="true">▷</i>Execution View</span><i aria-hidden="true">{executionViewOpen ? '−' : '+'}</i></button>{executionViewOpen && <div className="nav-children"><NavLink to="/sprints">Sprint View</NavLink></div>}</div>}
      {user.role === 'admin' && <div className="nav-group"><button className="nav-parent" onClick={() => setAppSettingOpen(value => !value)} aria-expanded={appSettingOpen}><span>App Setting</span><i aria-hidden="true">{appSettingOpen ? '−' : '+'}</i></button>{appSettingOpen && <div className="nav-subgroups"><div className="nav-group"><button className="nav-subparent" onClick={() => setPortfolioSyncOpen(value => !value)} aria-expanded={portfolioSyncOpen}><span>Portfolio Sync</span><i aria-hidden="true">{portfolioSyncOpen ? '−' : '+'}</i></button>{portfolioSyncOpen && <div className="nav-children"><NavLink to="/sync">Sync Monitoring</NavLink></div>}</div><div className="nav-group"><button className="nav-subparent" onClick={() => setConfigurationOpen(value => !value)} aria-expanded={configurationOpen}><span>Configuration</span><i aria-hidden="true">{configurationOpen ? '−' : '+'}</i></button>{configurationOpen && <div className="nav-children"><div className="nav-nested"><button className="nav-nested-parent" onClick={() => setViewConfigOpen(value => !value)} aria-expanded={viewConfigOpen}><span>View Config</span><i aria-hidden="true">{viewConfigOpen ? '−' : '+'}</i></button>{viewConfigOpen && <div className="nav-nested-children"><NavLink to="/traceability">Traceability Level Config</NavLink><NavLink to="/sprint-view-configuration">Sprint View Level Config</NavLink></div>}</div><div className="nav-nested"><button className="nav-nested-parent" onClick={() => setGridConfigOpen(value => !value)} aria-expanded={gridConfigOpen}><span>Grid Config</span><i aria-hidden="true">{gridConfigOpen ? '−' : '+'}</i></button>{gridConfigOpen && <div className="nav-nested-children"><NavLink to="/traceability-grid-configuration">Traceability Grid Config</NavLink><NavLink to="/sprint-grid-configuration">Sprint Grid Config</NavLink></div>}</div></div>}</div><div className="nav-group"><button className="nav-subparent" onClick={() => setMaintenanceOpen(value => !value)} aria-expanded={maintenanceOpen}><span>Maintenance</span><i aria-hidden="true">{maintenanceOpen ? '−' : '+'}</i></button>{maintenanceOpen && <div className="nav-children"><NavLink to="/configuration">Jira connection</NavLink><NavLink to="/maintenance">Project data</NavLink><NavLink to="/users">User management</NavLink></div>}</div></div>}</div>}
      {can('documentation') && <div className="nav-group"><button className="nav-parent" onClick={() => setDocumentationOpen(value => !value)} aria-expanded={documentationOpen}><span className="nav-title"><i aria-hidden="true">▤</i>Documentation</span><i aria-hidden="true">{documentationOpen ? '−' : '+'}</i></button>{documentationOpen && <div className="nav-children"><NavLink to="/documentation/configuration">Config document</NavLink><NavLink to="/documentation/api">API document</NavLink><NavLink to="/documentation/data-model">Data Model</NavLink><NavLink to="/documentation/grafana">Grafana Integration</NavLink></div>}</div>}
    </nav><div className="security"><strong>{user.display_name}</strong><span>{user.role === 'admin' ? 'Administrator' : 'Application user'}</span><button onClick={onLogout}>Sign out</button><small>Designed and Developed by VJNR MES Team</small></div></aside>
    <main>
      {notice && <div className="notice" role="status">{notice}<button onClick={() => setNotice('')} aria-label="Dismiss">×</button></div>}
      <Routes>
        <Route path="/" element={<Navigate to={homePath} replace/>}/>
        <Route path="/overview" element={<ScreenGate allowed={can('overview')}><><PageHeader eyebrow="EXECUTIVE PORTFOLIO" title="Portfolio overview" subtitle={projectLabel} configured={health.data?.jira_configured}/><Overview summary={summary.data} groups={statusGroups.data?.groups} projects={activeProjects}/></></ScreenGate>}/>
        <Route path="/portfolio-metrics" element={<ScreenGate allowed={can('overview')}><PortfolioMetricsPage configured={health.data?.jira_configured}/></ScreenGate>}/>
        <Route path="/project-plan" element={<ScreenGate allowed={user.role === 'admin'}><ProjectPlanPage configured={health.data?.jira_configured} onNotice={setNotice}/></ScreenGate>}/>
        <Route path="/hierarchy" element={<ScreenGate allowed={can('hierarchy')}><HierarchyPage projects={projects.data?.items ?? []} fields={fields.data?.items ?? []} configured={health.data?.jira_configured}/></ScreenGate>}/>
        <Route path="/cards" element={<ScreenGate allowed={can('traceability')}><CardViewPage projects={projects.data?.items ?? []} fields={fields.data?.items ?? []} configured={health.data?.jira_configured}/></ScreenGate>}/>
        <Route path="/wbs" element={<ScreenGate allowed={can('wbs')}><WbsViewPage projects={projects.data?.items ?? []} configured={health.data?.jira_configured}/></ScreenGate>}/>
        <Route path="/sprints" element={<ScreenGate allowed={can('sprints')}><SprintViewPage projects={projects.data?.items ?? []} configured={health.data?.jira_configured}/></ScreenGate>}/>
        <Route path="/traceability" element={<><PageHeader eyebrow="TRACEABILITY" title="Traceability configuration" subtitle="Choose a project and define its grouping hierarchy." configured={health.data?.jira_configured}/><TraceabilityConfiguration projects={projects.data?.items ?? []} fields={fields.data?.items ?? []} onNotice={setNotice}/></>}/>
        <Route path="/grid-configuration" element={<Navigate to="/traceability-grid-configuration" replace/>}/>
        <Route path="/traceability-grid-configuration" element={<GridConfiguration scope="traceability" projects={projects.data?.items ?? []} configured={health.data?.jira_configured} onNotice={setNotice}/>}/>
        <Route path="/sprint-grid-configuration" element={<GridConfiguration scope="sprint" projects={projects.data?.items ?? []} configured={health.data?.jira_configured} onNotice={setNotice}/>}/>
        <Route path="/sprint-view-configuration" element={<SprintViewConfiguration projects={projects.data?.items ?? []} configured={health.data?.jira_configured} onNotice={setNotice}/>}/>
        <Route path="/documentation/configuration" element={<ScreenGate allowed={can('documentation')}><ConfigurationDocument configured={health.data?.jira_configured}/></ScreenGate>}/>
        <Route path="/documentation/api" element={<ScreenGate allowed={can('documentation')}><ApiDocument configured={health.data?.jira_configured}/></ScreenGate>}/>
        <Route path="/documentation/data-model" element={<ScreenGate allowed={can('documentation')}><DataModelDocument configured={health.data?.jira_configured}/></ScreenGate>}/>
        <Route path="/documentation/grafana" element={<ScreenGate allowed={can('documentation')}><><GrafanaIntegrationDocument configured={health.data?.jira_configured}/><GrafanaWbsDocument/></></ScreenGate>}/>
        <Route path="/sync" element={<><PageHeader eyebrow="DATA OPERATIONS" title="Sync monitor" subtitle={projectLabel} configured={health.data?.jira_configured}/><section className="sync-panel"><div className="sync-heading"><div><p className="eyebrow">{projectLabel}</p><h2>Issue synchronization</h2><p>Enhanced-JQL sync with a five-minute incremental overlap and full reconciliation.</p></div><div className="actions"><button className="secondary" disabled={busy || !projectIds.length} onClick={() => sync.mutate({mode: 'incremental', projectIds})}>Incremental sync</button><button disabled={busy || !projectIds.length} onClick={() => sync.mutate({mode: 'full', projectIds})}>{sync.isPending ? 'Synchronizing…' : 'Full sync'}</button></div></div><div className="metrics"><Metric label="Last status" value={syncStatus.data?.latest?.status ?? 'Not run'}/><Metric label="Issues fetched" value={syncStatus.data?.latest?.fetched_count ?? 0}/><Metric label="Missing/tombstoned" value={syncStatus.data?.latest?.missing_count ?? 0}/><Metric label="Hierarchy anomalies" value={anomalies.data?.total_count ?? 0}/></div></section></>}/>
        <Route path="/configuration" element={<ConfigurationPage configured={health.data?.jira_configured} busy={busy} projects={projects.data?.items ?? []} projectsLoading={projects.isLoading} projectsError={projects.error} onTest={() => test.mutate()} onRefresh={() => refresh.mutate()} refreshing={refresh.isPending} onProjectSelect={(id, selected) => projectSelect.mutate({id, selected})} onNotice={setNotice}/>}/>
        <Route path="/maintenance" element={<ScreenGate allowed={user.role === 'admin'}><MaintenancePage projects={projects.data?.items ?? []} configured={health.data?.jira_configured} onNotice={setNotice}/></ScreenGate>}/>
        <Route path="/users" element={<ScreenGate allowed={user.role === 'admin'}><UserManagement currentUser={user} onNotice={setNotice}/></ScreenGate>}/>
        <Route path="/access-denied" element={<section className="access-denied"><span>403</span><h1>Screen access not assigned</h1><p>Ask an application administrator to add the required screen to your local user account.</p>{homePath !== '/access-denied' && <Link to={homePath}>Go to an available screen</Link>}</section>}/>
        <Route path="*" element={<Navigate to={homePath} replace/>}/>
      </Routes>
    </main>
  </div>
}

function PageHeader({eyebrow, title, subtitle, configured}: {eyebrow: string; title: string; subtitle: string; configured?: boolean}) { return <header><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="subtitle">{subtitle}</p></div><span className={`pill ${configured ? 'ok' : ''}`}>{configured ? 'Jira configured' : 'Setup required'}</span></header> }

function PortfolioMetricsPage({configured}: {configured?: boolean}) {
  const metrics = useQuery({queryKey: ['live-portfolio-metrics'], queryFn: api.portfolioMetrics, enabled: Boolean(configured), staleTime: 0})
  const formatTime = (value?: string) => value ? new Intl.DateTimeFormat(undefined, {dateStyle: 'medium', timeStyle: 'short'}).format(new Date(value)) : 'Not loaded'
  return <><PageHeader eyebrow="LIVE JIRA INTELLIGENCE" title="Portfolio Metrics" subtitle="Standard Jira delivery, schedule, ownership and activity metrics for every active project." configured={configured}/><section className="live-metrics-toolbar"><div><span className="live-indicator"><i/>LIVE FROM JIRA</span><p>Counts are evaluated by Jira using standard JQL fields. Synchronized SQLite issue data is not read or updated.</p></div><div><small>Last requested {formatTime(metrics.data?.generated_at)}</small><button className="secondary" onClick={() => metrics.refetch()} disabled={metrics.isFetching || !configured}>{metrics.isFetching ? 'Refreshing Jira…' : 'Refresh live metrics'}</button></div></section>{metrics.isLoading && <div className="live-metrics-state"><strong>Requesting current metrics from Jira…</strong><p>Large portfolios can take a moment because every count is evaluated in Jira.</p></div>}{metrics.error && <div className="live-metrics-state error"><strong>Jira metrics could not be loaded</strong><p>{metrics.error.message}</p><button onClick={() => metrics.refetch()}>Try again</button></div>}{metrics.data && metrics.data.items.length === 0 && <div className="live-metrics-state"><strong>No active projects</strong><p>Enable at least one project in Jira connection to show its live metrics.</p></div>}{metrics.data && <div className="live-project-grid">{metrics.data.items.map(item => <article className="live-project-panel" key={item.project_id}><div className="live-project-head"><span>{item.key}</span><div><h2>{item.name}</h2><small>Jira project ID {item.project_id}</small></div><b>{item.metrics.total}</b></div><div className="live-metric-section"><strong>Delivery status</strong><div className="live-project-metrics"><LiveMetric icon="◫" label="Total work items" value={item.metrics.total}/><LiveMetric icon="◇" label="Open unresolved" value={item.metrics.open}/><LiveMetric icon="○" label="To do" value={item.metrics.to_do}/><LiveMetric icon="◔" label="In progress" value={item.metrics.in_progress} tone="blue"/><LiveMetric icon="✓" label="Done" value={item.metrics.done} tone="green"/><LiveMetric icon="◇" label="Unassigned open" value={item.metrics.unassigned}/></div></div><div className="live-metric-section"><strong>Schedule health</strong><div className="live-project-metrics"><LiveMetric icon="!" label="Overdue open" value={item.metrics.overdue} tone="red"/><LiveMetric icon="◆" label="Due today" value={item.metrics.due_today}/><LiveMetric icon="›" label="Due next 7 days" value={item.metrics.due_next_7_days} tone="blue"/><LiveMetric icon="»" label="Due next 30 days" value={item.metrics.due_next_30_days} tone="blue"/><LiveMetric icon="▣" label="Open with due date" value={item.metrics.open_with_due_date}/><LiveMetric icon="∅" label="Open without due date" value={item.metrics.no_due_date}/></div></div><div className="live-metric-section"><strong>Recent activity</strong><div className="live-project-metrics"><LiveMetric icon="+" label="Created · 7 days" value={item.metrics.created_last_7_days}/><LiveMetric icon="+" label="Created · 30 days" value={item.metrics.created_last_30_days}/><LiveMetric icon="↻" label="Updated · 7 days" value={item.metrics.updated_last_7_days} tone="blue"/><LiveMetric icon="…" label="Stale open · 30 days" value={item.metrics.stale_open_30_days} tone="red"/><LiveMetric icon="↗" label="Resolved · 7 days" value={item.metrics.resolved_last_7_days} tone="green"/><LiveMetric icon="↗" label="Resolved · 30 days" value={item.metrics.resolved_last_30_days} tone="green"/></div></div></article>)}</div>}<p className="live-metrics-footnote">Jira returns approximate counts for JQL queries. These metrics use only standard Project, Status category, Resolution, Due date, Assignee, Created, Updated and Resolved fields. Priority names, workflow statuses and custom fields are intentionally excluded because their configuration varies by Jira site.</p></>
}

function LiveMetric({icon, label, value, tone = ''}: {icon: string; label: string; value: number; tone?: string}) { return <div className={`live-project-metric ${tone}`}><span aria-hidden="true">{icon}</span><small>{label}</small><strong>{value.toLocaleString()}</strong></div> }

function ProjectPlanPage({configured, onNotice}: {configured?: boolean; onNotice: (message: string) => void}) {
  const queryClient = useQueryClient()
  const plans = useQuery({queryKey: ['project-plans'], queryFn: api.projectPlans})
  return <><PageHeader eyebrow="PORTFOLIO GOVERNANCE" title="Project Plan" subtitle="Maintain project start dates and an auditable sequence of end-date baselines." configured={configured}/><section className="plan-intro"><div><span aria-hidden="true">◆</span><div><strong>Baseline history is preserved</strong><p>The first end date becomes Baseline 1. Entering a different end date appends Baseline 2, 3 and onward without overwriting prior dates.</p></div></div><small>Stored locally in SQLite · Jira is not modified</small></section>{plans.isLoading ? <State text="Loading active project plans…"/> : plans.error ? <State text={plans.error.message}/> : <div className="plan-grid">{plans.data?.items.map(plan => <ProjectPlanPanel key={plan.project_id} plan={plan} onSaved={saved => { queryClient.setQueryData<{items: ProjectPlan[]}>(['project-plans'], current => ({items: (current?.items ?? []).map(item => item.project_id === saved.project_id ? saved : item)})); queryClient.invalidateQueries({queryKey: ['project-plans']}); onNotice(`${saved.key} project plan and governance details saved.`) }}/>)}</div>}</>
}

function ProjectPlanPanel({plan, onSaved}: {plan: ProjectPlan; onSaved: (plan: ProjectPlan) => void}) {
  const [startDate, setStartDate] = useState(plan.start_date ?? '')
  const [endDate, setEndDate] = useState(plan.latest_baseline_date ?? '')
  const [projectStatus, setProjectStatus] = useState(plan.project_status ?? '')
  const [managementSupport, setManagementSupport] = useState(plan.management_support ?? '')
  useEffect(() => { setStartDate(plan.start_date ?? ''); setEndDate(plan.latest_baseline_date ?? ''); setProjectStatus(plan.project_status ?? ''); setManagementSupport(plan.management_support ?? '') }, [plan.start_date, plan.latest_baseline_date, plan.project_status, plan.management_support])
  const save = useMutation({mutationFn: () => api.saveProjectPlan(plan.project_id, startDate, endDate, projectStatus || null, managementSupport), onSuccess: onSaved})
  const dateLabel = (value: string) => new Intl.DateTimeFormat(undefined, {dateStyle: 'medium', timeZone: 'UTC'}).format(new Date(`${value}T00:00:00Z`))
  const newBaseline = Boolean(plan.latest_baseline_date && endDate && endDate !== plan.latest_baseline_date)
  return <article className="plan-panel"><header><span>{plan.key}</span><div><h2>{plan.name}</h2><small>Jira project ID {plan.project_id}</small></div>{plan.latest_baseline_version > 0 && <b>{plan.latest_baseline_version} baseline{plan.latest_baseline_version === 1 ? '' : 's'}</b>}</header><div className="plan-fields"><label>Project start date<input type="date" value={startDate} onChange={event => setStartDate(event.target.value)}/></label><label>{plan.latest_baseline_version ? `New or current end date` : 'Baseline 1 end date'}<input type="date" min={startDate} value={endDate} onChange={event => setEndDate(event.target.value)}/></label></div><div className="plan-governance-fields"><label>Project Status (RAG)<select value={projectStatus} onChange={event => setProjectStatus(event.target.value)}><option value="">Select status</option><option value="Green">Green — On Track</option><option value="Amber">Amber — At Risk</option><option value="Red">Red — Needs Attention</option></select></label><label>Support Required from Management<textarea rows={3} maxLength={4000} placeholder="Describe decisions, approvals, resources or escalations required…" value={managementSupport} onChange={event => setManagementSupport(event.target.value)}/></label></div>{plan.baselines.length > 0 && <div className="baseline-history"><strong>Baseline history</strong>{plan.baselines.map(item => <span className={item.version === plan.latest_baseline_version ? 'latest' : ''} key={item.version}><b>B{item.version}</b>{dateLabel(item.end_date)}{item.version === plan.latest_baseline_version && <i>Latest</i>}</span>)}</div>}{save.error && <p className="plan-error">{save.error.message}</p>}<button disabled={!startDate || !endDate || save.isPending} onClick={() => save.mutate()}>{save.isPending ? 'Saving…' : newBaseline ? `Add Baseline ${plan.latest_baseline_version + 1}` : plan.latest_baseline_version ? 'Save project dates' : 'Create Baseline 1'}</button></article>
}

function MaintenancePage({projects, configured, onNotice}: {projects: Project[]; configured?: boolean; onNotice: (message: string) => void}) {
  const queryClient = useQueryClient()
  const [projectId, setProjectId] = useState('')
  const [confirmation, setConfirmation] = useState('')
  const project = projects.find(item => item.jira_project_id === projectId)
  const remove = useMutation({
    mutationFn: () => api.deleteProjectData(projectId),
    onSuccess: data => {
      setProjectId('')
      setConfirmation('')
      queryClient.invalidateQueries()
      onNotice(`Deleted all local SQLite data for ${data.project_key}: ${data.deleted.issues ?? 0} issues removed.`)
    },
    onError: error => onNotice(error.message),
  })
  const confirmed = Boolean(project && confirmation === project.key)
  return <><PageHeader eyebrow="APP SETTING · MAINTENANCE" title="Local data maintenance" subtitle="Permanently remove one Jira project's data from this application's SQLite database." configured={configured}/><section className="maintenance-card"><div className="maintenance-warning"><span aria-hidden="true">!</span><div><strong>Permanent local deletion</strong><p>This does not delete or modify anything in Jira. It removes the selected project, synchronized issues, hierarchy records, due-date history, project configurations, and project-scoped metadata from SQLite.</p></div></div><div className="maintenance-form"><label>Project<select value={projectId} onChange={event => { setProjectId(event.target.value); setConfirmation('') }}><option value="">Select a project…</option>{projects.map(item => <option key={item.jira_project_id} value={item.jira_project_id}>{item.key} · {item.name} · Jira ID {item.jira_project_id}</option>)}</select></label>{project && <><div className="maintenance-scope"><strong>Data scheduled for deletion</strong><ul><li>Project record and locally synchronized work items</li><li>Field values, due-date changelog facts, hierarchy links, and anomalies</li><li>Traceability, Sprint View, and both grid configurations</li><li>Metadata contexts scoped only to {project.key}</li></ul><p>Shared Jira field, status, and issue-type catalogs are retained for other projects.</p></div><label>Type <b>{project.key}</b> to confirm<input value={confirmation} onChange={event => setConfirmation(event.target.value)} autoComplete="off" placeholder={project.key}/></label><button className="danger-action" disabled={!confirmed || remove.isPending} onClick={() => remove.mutate()}>{remove.isPending ? 'Deleting local data…' : `Delete ${project.key} from SQLite`}</button></>}</div></section></>
}

function ConfigurationPage({configured, busy, projects, projectsLoading, projectsError, onTest, onRefresh, refreshing, onProjectSelect, onNotice}: {configured?: boolean; busy: boolean; projects: Project[]; projectsLoading: boolean; projectsError: Error | null; onTest: () => void; onRefresh: () => void; refreshing: boolean; onProjectSelect: (id: string, selected: boolean) => void; onNotice: (message: string) => void}) {
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [projectSearch, setProjectSearch] = useState('')
  const [projectStatus, setProjectStatus] = useState('all')
  const [fieldKind, setFieldKind] = useState('all')
  const [fieldSync, setFieldSync] = useState('all')
  const [catalogProjectId, setCatalogProjectId] = useState('')
  const catalog = useQuery({queryKey: ['field-catalog', search, catalogProjectId], queryFn: () => api.fields(search, catalogProjectId)})
  const filteredProjects = projects.filter(project => {
    const term = projectSearch.trim().toLocaleLowerCase()
    return (!term || `${project.key} ${project.name} ${project.jira_project_id}`.toLocaleLowerCase().includes(term)) && (projectStatus === 'all' || (projectStatus === 'active') === project.active)
  })
  const filteredFields = (catalog.data?.items ?? []).filter(field => (fieldKind === 'all' || (fieldKind === 'custom') === field.is_custom) && (fieldSync === 'all' || (fieldSync === 'included') === field.selected))
  const refreshCatalog = () => { queryClient.invalidateQueries({queryKey: ['field-catalog']}); queryClient.invalidateQueries({queryKey: ['fields']}) }
  const fieldSelect = useMutation({mutationFn: ({id, selected}: {id: string; selected: boolean}) => api.selectField(id, selected), onSuccess: refreshCatalog, onError: error => onNotice(error.message)})
  const bulkSelect = useMutation({mutationFn: (selected: boolean) => api.selectFields(filteredFields.map(field => field.jira_field_id), selected), onSuccess: data => { onNotice(`${data.updated_count} filtered fields ${data.selected ? 'included in' : 'excluded from'} synchronization.`); refreshCatalog() }, onError: error => onNotice(error.message)})
  const selectedProject = projects.find(project => project.jira_project_id === catalogProjectId)
  const chooseCatalogProject = (projectId: string) => setCatalogProjectId(current => current === projectId ? '' : projectId)
  return <>
    <PageHeader eyebrow="ADMINISTRATION" title="Connect your portfolio" subtitle="Discover Jira projects and fields without site-specific assumptions." configured={configured}/>
    <section className="connection"><div><span className="step">01</span><h2>Jira Cloud connection</h2><p>Credentials are configured in the backend environment.</p></div><div className="actions"><button className="secondary" disabled={busy || !configured} onClick={onTest}>Test connection</button><button disabled={busy || !configured} onClick={onRefresh}>{refreshing ? 'Discovering…' : 'Refresh metadata'}</button></div></section>
    <div className="grid">
      <section className="card projects">
        <div className="cardhead"><div><span className="step">02</span><h2>Projects</h2></div><span>{filteredProjects.length} of {projects.length}</span></div>
        <div className="panel-filter-bar"><label><span>Search</span><input value={projectSearch} onChange={event => setProjectSearch(event.target.value)} placeholder="Project name, key, or ID…"/></label><label><span>Status</span><select value={projectStatus} onChange={event => setProjectStatus(event.target.value)}><option value="all">All projects</option><option value="active">Active</option><option value="inactive">Inactive</option></select></label>{(projectSearch || projectStatus !== 'all') && <button className="secondary" onClick={() => { setProjectSearch(''); setProjectStatus('all') }}>Clear</button>}</div>
        {projectsLoading ? <State text="Loading projects…"/> : projectsError ? <State text={projectsError.message}/> : filteredProjects.length ? <div className="list">{filteredProjects.map(project => <div className={`row project-config-row ${catalogProjectId === project.jira_project_id ? 'catalog-selected' : ''}`} key={project.jira_project_id}><label className="catalog-project-check"><input type="checkbox" checked={catalogProjectId === project.jira_project_id} onChange={() => chooseCatalogProject(project.jira_project_id)}/><span className="sr-only">Show fields applicable to {project.name}</span></label><div className="identity"><b>{project.key}</b><div><strong>{project.name}</strong><small>Jira ID {project.jira_project_id}</small></div></div><div className="project-active-control"><span>Active</span><Toggle checked={project.active} label={`Activate ${project.name}`} onChange={selected => onProjectSelect(project.jira_project_id, selected)}/></div></div>)}</div> : <State text={projects.length ? "No projects match the filters." : "Refresh metadata to discover projects."}/>} 
      </section>
      <section className="card fields">
        <div className="cardhead field-catalog-head"><div><span className="step">03</span><h2>Field catalog</h2><small>{selectedProject ? `${selectedProject.key} · Applicable fields` : 'All discovered fields'}</small></div><span>{filteredFields.length} of {catalog.data?.total_count ?? '—'}</span></div>
        <div className="field-filter-bar"><label><span>Search</span><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Field name or Jira ID…"/></label><label><span>Field type</span><select value={fieldKind} onChange={event => setFieldKind(event.target.value)}><option value="all">All fields</option><option value="standard">Standard</option><option value="custom">Custom</option></select></label><label><span>Sync status</span><select value={fieldSync} onChange={event => setFieldSync(event.target.value)}><option value="all">All statuses</option><option value="included">Included</option><option value="excluded">Excluded</option></select></label></div>
        <div className="field-bulk-bar"><span>Bulk action applies to <strong>{filteredFields.length}</strong> filtered fields</span><div><button className="secondary" disabled={!filteredFields.length || bulkSelect.isPending} onClick={() => bulkSelect.mutate(true)}>Include all</button><button className="secondary exclude-all" disabled={!filteredFields.length || bulkSelect.isPending} onClick={() => bulkSelect.mutate(false)}>Exclude all</button>{(search || fieldKind !== 'all' || fieldSync !== 'all') && <button className="secondary" onClick={() => { setSearch(''); setFieldKind('all'); setFieldSync('all') }}>Clear filters</button>}</div></div>
        {catalog.isLoading ? <State text="Loading fields…"/> : catalog.error ? <State text={catalog.error.message}/> : filteredFields.length ? <div className="list">{filteredFields.map(field => <div className="row" key={field.jira_field_id}><div><strong>{field.name}</strong><small><code>{field.jira_field_id}</code> · {fieldType(field)} {field.is_custom && '· Custom'}</small></div><Toggle checked={field.selected} label={`Select ${field.name}`} onChange={selected => fieldSelect.mutate({id: field.jira_field_id, selected})}/></div>)}</div> : <State text="No fields match the selected filters."/>}
      </section>
    </div>
  </>
}

const screenLabels: Record<string, string> = {
  overview: 'Portfolio Overview', hierarchy: 'Hierarchy', traceability: 'Traceability', wbs: 'WBS View', sprints: 'Sprint View', documentation: 'Documentation',
}

function UserManagement({currentUser, onNotice}: {currentUser: AppUser; onNotice: (message: string) => void}) {
  const queryClient = useQueryClient()
  const users = useQuery({queryKey: ['app-users'], queryFn: api.users})
  const empty: UserPayload = {username: '', display_name: '', password: '', role: 'user', screen_permissions: ['overview'], active: true}
  const [form, setForm] = useState<UserPayload>(empty)
  const [editingId, setEditingId] = useState<number | null>(null)
  const reset = () => { setEditingId(null); setForm(empty) }
  const save = useMutation({
    mutationFn: () => editingId ? api.updateUser(editingId, form) : api.createUser(form),
    onSuccess: () => { onNotice(editingId ? 'User updated.' : 'User created.'); reset(); queryClient.invalidateQueries({queryKey: ['app-users']}) },
    onError: error => onNotice(error.message),
  })
  const remove = useMutation({mutationFn: api.deleteUser, onSuccess: () => { onNotice('User deleted.'); queryClient.invalidateQueries({queryKey: ['app-users']}) }, onError: error => onNotice(error.message)})
  const edit = (user: AppUser) => { setEditingId(user.id); setForm({username: user.username, display_name: user.display_name, password: '', role: user.role, screen_permissions: user.screen_permissions, active: user.active}) }
  const toggleScreen = (screen: string) => setForm(value => ({...value, screen_permissions: value.screen_permissions.includes(screen) ? value.screen_permissions.filter(item => item !== screen) : [...value.screen_permissions, screen]}))
  return <><PageHeader eyebrow="APP SETTING · CONFIGURATION" title="User management" subtitle="Manage local users and the application screens they can access." configured/><div className="user-management"><section className="user-editor"><div className="cardhead"><div><span className="step">{editingId ? 'EDIT USER' : 'NEW USER'}</span><h2>{editingId ? 'Modify local account' : 'Add local account'}</h2></div>{editingId && <button className="secondary" onClick={reset}>Cancel</button>}</div><form onSubmit={event => { event.preventDefault(); save.mutate() }}><div className="user-fields"><label>Username<input value={form.username} onChange={event => setForm({...form, username: event.target.value})} required minLength={3}/></label><label>Display name<input value={form.display_name} onChange={event => setForm({...form, display_name: event.target.value})} required/></label><label>Password<input type="password" autoComplete="new-password" value={form.password ?? ''} onChange={event => setForm({...form, password: event.target.value})} required={!editingId} minLength={8} placeholder={editingId ? 'Leave blank to keep current password' : 'Minimum 8 characters'}/></label><label>Role<select value={form.role} onChange={event => setForm({...form, role: event.target.value as 'admin' | 'user'})}><option value="user">User</option><option value="admin">Administrator</option></select></label></div><div className={`screen-access ${form.role === 'admin' ? 'disabled' : ''}`}><div><strong>Screen access</strong><span>{form.role === 'admin' ? 'Administrators can access every screen.' : 'Choose the screens visible to this user.'}</span></div><div className="screen-options">{(users.data?.screens ?? Object.keys(screenLabels)).map(screen => <label key={screen}><input type="checkbox" checked={form.role === 'admin' || form.screen_permissions.includes(screen)} disabled={form.role === 'admin'} onChange={() => toggleScreen(screen)}/><span>{screenLabels[screen] ?? screen}</span></label>)}</div></div><label className="active-user"><input type="checkbox" checked={form.active} onChange={event => setForm({...form, active: event.target.checked})}/> Active account</label><button disabled={save.isPending}>{save.isPending ? 'Saving…' : editingId ? 'Save changes' : 'Add user'}</button></form></section><section className="user-list"><div className="cardhead"><div><span className="step">LOCAL ACCOUNTS</span><h2>Application users</h2></div><span>{users.data?.items.length ?? 0} users</span></div>{users.isLoading ? <State text="Loading users…"/> : <div className="user-rows">{users.data?.items.map(user => <article className={!user.active ? 'inactive' : ''} key={user.id}><div className="user-avatar">{user.display_name.slice(0, 2).toUpperCase()}</div><div><strong>{user.display_name}</strong><span>@{user.username} · {user.role}</span><small>{user.role === 'admin' ? 'All screens' : user.screen_permissions.map(screen => screenLabels[screen] ?? screen).join(', ') || 'No screens assigned'}</small></div><div className="user-actions"><button className="secondary" onClick={() => edit(user)}>Edit</button><button className="danger" disabled={user.username === 'admin' || user.id === currentUser.id || remove.isPending} onClick={() => { if (window.confirm(`Delete ${user.display_name}?`)) remove.mutate(user.id) }}>Delete</button></div></article>)}</div>}</section></div></>
}

function ConfigurationDocument({configured}: {configured?: boolean}) {
  const steps = [
    {number: '01', title: 'Connect Jira and discover metadata', path: '/configuration', purpose: 'Establish read-only access and discover projects, standard fields, custom fields, issue types and statuses directly from Jira.', action: 'Open App Setting → Maintenance → Jira connection. Confirm the backend environment credentials, test the connection, refresh metadata, and activate only the projects that should appear in the portfolio. Use the project search and Active/Inactive filter to manage large catalogs.', result: 'The discovered project and field catalogs become the source for later configuration. No custom-field IDs or hierarchy assumptions are hardcoded.'},
    {number: '02', title: 'Synchronize portfolio data', path: '/sync', purpose: 'Copy selected Jira project data into the local SQLite reporting model so portfolio pages can aggregate it quickly.', action: 'Run Full sync for the first load and after major field changes. Use Incremental sync for routine updates. Review fetched, missing and hierarchy-anomaly counts.', result: 'Issues, hierarchy links, statuses, due dates and due-date history are available to reporting views. Newly selected fields may need another sync before values appear.'},
    {number: '03', title: 'Configure Traceability levels', path: '/traceability', purpose: 'Define the business drill-down used by Traceability, Hierarchy and WBS for each project.', action: 'Choose a project, add grouping levels in order, select a Jira field for every level, enter clear card captions, and save. Hierarchy limits its grouping selectors to metadata applicable to the project selected in its header.', result: 'Traceability opens at level 1 and reveals each child level. The bottom level opens the work-item grid. Multi-value fields such as Labels can place an issue in multiple groups.'},
    {number: '04', title: 'Configure Sprint View levels', path: '/sprint-view-configuration', purpose: 'Create an execution-focused drill-down independently from portfolio Traceability.', action: 'Choose the project, select Jira metadata fields that represent the execution breakdown, add administrator-friendly captions, and save.', result: 'Sprint View uses this project-specific sequence. Changes here do not alter Traceability grouping.'},
    {number: '05', title: 'Select synchronized fields and configure grids', path: '/configuration', purpose: 'Limit synchronized custom data and control the work-item details shown after a user reaches the lowest grouping level.', action: 'In Jira connection, check a project to show only its applicable fields. Filter by field type or sync status, then use Include all or Exclude all for the filtered set. Run a Full sync after changing field inclusion. Under Grid Config, configure Traceability Grid and Sprint Grid separately and arrange optional columns.', result: 'Permission-limited or non-applicable custom fields are excluded from project catalogs. Mandatory grid columns remain fixed, while optional columns are project- and view-specific.'},
    {number: '06', title: 'Configure local users', path: '/users', purpose: 'Control who can sign in and which application screens each non-administrator can open.', action: 'Open App Setting → Maintenance → User management, add a username, display name and temporary password, then select the permitted screens. Use Edit to change access or reset a password; deactivate an account to retain it without allowing sign-in.', result: 'Administrators retain access to every screen. Standard users see only assigned menus and are redirected if they try to open an unassigned route.'},
    {number: '07', title: 'Maintain project plan baselines', path: '/project-plan', purpose: 'Record the approved project start and end dates independently from Jira issue due dates while retaining every approved end-date revision.', action: 'Enter the project start and first approved end date to create Baseline 1. When the approved end changes, enter the new date to append Baseline 2, 3 and onward. Saving the same end date does not create a duplicate.', result: 'SQLite preserves the original and every revised end-date baseline. Each individual Overview card shows Project start, Baseline 1 end and the latest numbered baseline end.'},
    {number: '08', title: 'Review live Portfolio Metrics', path: '/portfolio-metrics', purpose: 'Inspect current project health directly from Jira without calculating from synchronized SQLite issue rows.', action: 'Open Portfolio Metrics or select Refresh live metrics. Review Delivery status, Schedule health and Recent activity for every active project.', result: 'The page shows 18 Jira-evaluated approximate counts using only standard fields. Workflow-specific statuses, priority names and custom fields are excluded.'},
    {number: '09', title: 'Maintain local project data', path: '/maintenance', purpose: 'Remove a retired or incorrectly synchronized project completely from the local SQLite reporting database.', action: 'Select one project, review the deletion scope, and type its project key to confirm. This permanent operation is local and never writes to Jira.', result: 'Project issues, date and baseline history, hierarchy facts, configurations and project-scoped metadata are removed while shared catalogs and other projects remain intact.'},
    {number: '10', title: 'Validate and operate', path: '/overview', purpose: 'Confirm that configured portfolio and execution views use the intended data source.', action: 'Verify project-plan dates on Overview cards, open WBS, refresh Portfolio Metrics, and test Traceability and Sprint View down to their grids.', result: 'Administrators can distinguish live Jira metrics, synchronized reporting calculations and locally governed project-plan dates.'},
  ]
  return <><PageHeader eyebrow="DOCUMENTATION · APP ADMIN" title="Configuration guide" subtitle="From Jira discovery to configured portfolio and execution views." configured={configured}/><section className="admin-guide"><div className="guide-intro"><div><span className="step">ADMIN WORKFLOW</span><h2>Configure in dependency order</h2><p>Each stage depends on the data produced by the stage before it. Complete connection and metadata discovery first, synchronize second, then configure grouping levels, grids and user access.</p></div><div className="guide-flow" aria-label="Configuration workflow"><span>Jira</span><i>→</i><span>Sync</span><i>→</i><span>Levels</span><i>→</i><span>Grids</span><i>→</i><span>Users</span></div></div><aside className="guide-note"><strong>Important:</strong> Configurations are saved per Jira project. Traceability and Sprint View have independent grouping and grid configurations. Change the default administrator password after first sign-in.</aside><div className="guide-steps">{steps.map(step => <article className="guide-step" key={step.number}><div className="guide-step-number">{step.number}</div><div className="guide-step-body"><div className="guide-step-heading"><h2>{step.title}</h2><Link to={step.path}>Open page <span aria-hidden="true">→</span></Link></div><dl><div><dt>Purpose</dt><dd>{step.purpose}</dd></div><div><dt>Administrator actions</dt><dd>{step.action}</dd></div><div><dt>Expected result</dt><dd>{step.result}</dd></div></dl></div></article>)}</div><section className="guide-reference"><div><span className="step">CONFIGURATION RESPONSIBILITIES</span><h2>What each configuration controls</h2></div><div className="guide-reference-grid"><article><strong>Jira connection</strong><p>Credentials, connectivity, metadata discovery and active-project selection.</p></article><article><strong>Portfolio Sync</strong><p>Reporting-data freshness, full versus incremental loads, missing issues and anomalies.</p></article><article><strong>Traceability levels</strong><p>Portfolio drill-down order and captions used by Traceability, Hierarchy and WBS.</p></article><article><strong>Sprint View levels</strong><p>Execution drill-down order and captions used only by Sprint View.</p></article><article><strong>Traceability Grid</strong><p>Optional Jira columns shown in the Traceability bottom-level grid.</p></article><article><strong>Sprint Grid</strong><p>Optional Jira columns shown in the Sprint View bottom-level grid.</p></article><article><strong>User management</strong><p>Local accounts, password resets, activation, administrator roles and per-screen access.</p></article></div></section><section className="guide-troubleshooting"><span className="step">ADMIN CHECKLIST</span><h2>When a value or field is missing</h2><ol><li>Confirm the correct Jira project is active and selected.</li><li>Refresh Jira metadata if the field was recently added or changed.</li><li>Confirm the field applies to that project and was added to the correct grid configuration.</li><li>Run a Full sync when a newly selected field has no synchronized values.</li><li>Check Sync Monitoring for failures, missing issues or hierarchy anomalies.</li></ol></section></section></>
}

function ApiDocument({configured}: {configured?: boolean}) {
  const groups = [
    {title: 'Authentication and users', description: 'Local sign-in, session identity and administrator-managed accounts.', endpoints: [['POST', '/auth/login', 'Create a 12-hour local session'], ['GET', '/auth/me', 'Read the signed-in user and screen permissions'], ['POST', '/auth/logout', 'Invalidate the current session'], ['GET', '/admin/users', 'List local users and available screens'], ['POST', '/admin/users', 'Create a local user'], ['PUT', '/admin/users/{user_id}', 'Update identity, password, role or access'], ['DELETE', '/admin/users/{user_id}', 'Delete a non-root user']]},
    {title: 'Service health and live architecture', description: 'Connectivity checks, live issue metadata, Jira-evaluated portfolio counts and the running database model.', endpoints: [['GET', '/health/live', 'Process liveness'], ['GET', '/health/ready', 'Database readiness and Jira configuration state'], ['POST', '/jira/test-connection', 'Validate Jira credentials'], ['GET', '/jira/issues/{issue_id_or_key}/metadata', 'Fetch live Jira metadata for one work item'], ['GET', '/jira/portfolio-metrics', 'Return 18 standard JQL counts for every active project directly from Jira'], ['GET', '/documentation/data-model', 'Read live SQLAlchemy tables, columns, foreign-key relationships and row counts']]},
    {title: 'Metadata and project administration', description: 'Dynamic discovery, selection, and local maintenance of Jira projects and fields.', endpoints: [['POST', '/admin/metadata/refresh', 'Refresh Jira metadata catalogs'], ['GET', '/jira/projects', 'List discovered projects'], ['PUT', '/admin/projects/{jira_project_id}', 'Activate or deactivate a project'], ['DELETE', '/admin/projects/{jira_project_id}/data?confirm={jira_project_id}', 'Permanently delete only this project’s local SQLite data and configuration'], ['GET', '/metadata/fields', 'List or search fields, optionally scoped by project ID'], ['GET', '/metadata/fields/{field_id}/options', 'List discovered field options'], ['PUT', '/admin/fields/{jira_field_id}', 'Select or deselect one synchronized field'], ['PUT', '/admin/fields', 'Include or exclude a filtered set of fields'], ['GET', '/metadata/issue-types', 'List issue types'], ['GET', '/metadata/statuses', 'List statuses']]},
    {title: 'Synchronization', description: 'Load Jira work items into SQLite and monitor data freshness.', endpoints: [['POST', '/admin/sync', 'Start full or incremental synchronization'], ['GET', '/admin/sync/runs', 'List synchronization history'], ['GET', '/admin/sync/status', 'Read active and latest run status']]},
    {title: 'Project plan, view and grid configuration', description: 'Project baseline history, grouping sequences, captions and grid columns.', endpoints: [['GET', '/project-plans', 'List active projects with start date and complete numbered baseline history'], ['PUT', '/admin/project-plans/{project_id}', 'Save the start date and append a changed end date as the next baseline'], ['GET', '/traceability-config/{project_id}', 'Read Traceability level configuration'], ['PUT', '/admin/traceability-config/{project_id}', 'Save Traceability levels and captions'], ['GET', '/sprint-view-config/{project_id}', 'Read Sprint View level configuration'], ['PUT', '/admin/sprint-view-config/{project_id}', 'Save Sprint View levels and captions'], ['GET', '/grid-config/{project_id}', 'Read Traceability grid configuration'], ['PUT', '/admin/grid-config/{project_id}', 'Save Traceability optional columns'], ['GET', '/sprint-grid-config/{project_id}', 'Read Sprint grid configuration'], ['PUT', '/admin/sprint-grid-config/{project_id}', 'Save Sprint optional columns'], ['GET', '/grid-config/{project_id}/fields', 'List fields applicable to a project']]},
    {title: 'Issues, hierarchy and portfolio', description: 'Read synchronized work items, hierarchy, portfolio summaries and WBS flow.', endpoints: [['GET', '/issues', 'Filter and list work items'], ['GET', '/issues/{jira_issue_id}', 'Read one synchronized work item'], ['GET', '/issues/{jira_issue_id}/children', 'List immediate children'], ['GET', '/hierarchy/roots', 'List hierarchy roots'], ['GET', '/hierarchy/epics', 'Find epics matching filters'], ['GET', '/hierarchy/anomalies', 'List detected hierarchy problems'], ['GET', '/portfolio/summary', 'Calculate portfolio KPIs'], ['GET', '/portfolio/wbs-flow/{project_id}', 'Build WBS flow data']]},
    {title: 'Analytics', description: 'Aggregate configured Jira fields for cards, charts and drill-downs.', endpoints: [['POST', '/analytics/group-by', 'Group filtered issues by a Jira field'], ['POST', '/analytics/card-groups', 'Calculate card groups and delivery metrics'], ['POST', '/analytics/timeseries', 'Calculate time-series analytics']]},
    {title: 'External integrations', description: 'Export configured application views in visualization-ready shapes.', endpoints: [['GET', '/integrations/grafana/traceability/cards/{project_id}', 'Export the complete calculated Traceability Card View JSON'], ['GET', '/integrations/grafana/wbs/{project_id}', 'Export the configured WBS Flow JSON']]},
  ] as const
  return <><PageHeader eyebrow="DOCUMENTATION · API" title="API document" subtitle="Administrator reference for the FastAPI service." configured={configured}/><section className="api-doc"><div className="api-overview"><div><span className="step">API BASICS</span><h2>Versioned REST interface</h2><p>All application endpoints use the <code>/api/v1</code> prefix. The frontend defaults to <code>http://localhost:8000</code> and can be changed with <code>VITE_API_URL</code>.</p></div><a href="http://localhost:8000/docs" target="_blank" rel="noreferrer">Open interactive Swagger docs ↗</a></div><div className="api-callouts"><article><strong>Session authorization</strong><p>Sign in through <code>/auth/login</code>, then send <code>Authorization: Bearer &lt;session-token&gt;</code>. Administrator endpoints also validate the signed-in role.</p></article><article><strong>Content and tracing</strong><p>Send JSON with <code>Content-Type: application/json</code>. Responses include <code>X-Request-ID</code>; clients may supply the same header for trace correlation.</p></article><article><strong>Error shape</strong><p>Errors return a code, human-readable message and request ID. Jira failures may also include structured details.</p></article></div><div className="api-groups">{groups.map(group => <section className="api-group" key={group.title}><div className="api-group-head"><h2>{group.title}</h2><p>{group.description}</p></div><div className="api-endpoints">{group.endpoints.map(([method, path, purpose]) => <div className="api-endpoint" key={`${method}-${path}`}><span className={`api-method ${method.toLowerCase()}`}>{method}</span><code>/api/v1{path}</code><p>{purpose}</p></div>)}</div></section>)}</div><section className="api-example"><span className="step">REQUEST EXAMPLE</span><h2>Start an incremental sync</h2><pre>{`curl -X POST http://localhost:8000/api/v1/admin/sync \\\n  -H "Content-Type: application/json" \\\n  -H "Authorization: Bearer $SESSION_TOKEN" \\\n  -d '{"mode":"incremental","project_ids":["10732"]}'`}</pre><p>Use Jira project IDs discovered from <code>GET /api/v1/jira/projects</code>. Never place Jira credentials or API tokens in browser requests.</p></section></section></>
}

type ModelPosition = {x: number; y: number; vx: number; vy: number}

function DataModelDocument({configured}: {configured?: boolean}) {
  const model = useQuery({queryKey: ['live-data-model'], queryFn: api.dataModel})
  const [positions, setPositions] = useState<Record<string, ModelPosition>>({})
  const [running, setRunning] = useState(true)
  const [selectedId, setSelectedId] = useState('')
  const [dragging, setDragging] = useState('')
  const svgRef = useRef<SVGSVGElement>(null)
  const initialize = (data: LiveDataModel) => setPositions(Object.fromEntries(data.nodes.map((node, index) => { const angle = index / Math.max(data.nodes.length, 1) * Math.PI * 2; const ring = 190 + (index % 3) * 42; return [node.id, {x: 550 + Math.cos(angle) * ring, y: 325 + Math.sin(angle) * ring, vx: 0, vy: 0}] })))
  useEffect(() => { if (model.data) { initialize(model.data); setSelectedId(current => current || model.data?.nodes[0]?.id || '') } }, [model.data])
  useEffect(() => {
    if (!running || !model.data) return
    const timer = window.setInterval(() => setPositions(current => {
      const next = Object.fromEntries(Object.entries(current).map(([id, point]) => [id, {...point}]))
      const ids = Object.keys(next)
      for (let left = 0; left < ids.length; left += 1) for (let right = left + 1; right < ids.length; right += 1) {
        const a = next[ids[left]], b = next[ids[right]], dx = a.x - b.x, dy = a.y - b.y, distanceSquared = Math.max(dx * dx + dy * dy, 900), force = 2600 / distanceSquared
        const distance = Math.sqrt(distanceSquared); a.vx += dx / distance * force; a.vy += dy / distance * force; b.vx -= dx / distance * force; b.vy -= dy / distance * force
      }
      for (const link of model.data.links) {
        const source = next[link.source], target = next[link.target]; if (!source || !target) continue
        const dx = target.x - source.x, dy = target.y - source.y, distance = Math.max(Math.sqrt(dx * dx + dy * dy), 1), force = (distance - 175) * .0018
        source.vx += dx / distance * force; source.vy += dy / distance * force; target.vx -= dx / distance * force; target.vy -= dy / distance * force
      }
      for (const id of ids) { const point = next[id]; point.vx += (550 - point.x) * .0005; point.vy += (325 - point.y) * .0005; point.vx *= .86; point.vy *= .86; if (id !== dragging) { point.x = Math.max(90, Math.min(1010, point.x + point.vx)); point.y = Math.max(38, Math.min(612, point.y + point.vy)) } }
      return next
    }), 32)
    return () => window.clearInterval(timer)
  }, [running, model.data, dragging])
  const moveDragged = (event: React.PointerEvent<SVGSVGElement>) => {
    if (!dragging || !svgRef.current) return
    const bounds = svgRef.current.getBoundingClientRect(), x = (event.clientX - bounds.left) / bounds.width * 1100, y = (event.clientY - bounds.top) / bounds.height * 650
    setPositions(current => ({...current, [dragging]: {x, y, vx: 0, vy: 0}}))
  }
  const selected = model.data?.nodes.find(node => node.id === selectedId)
  return <><PageHeader eyebrow="DOCUMENTATION · LIVE ARCHITECTURE" title="Data Model" subtitle="A physics-based view of the running database schema and its current records." configured={configured}/><section className="model-toolbar"><div><span className="live-indicator"><i/>LIVE SQLALCHEMY MODEL</span><p>Tables, columns, foreign keys and row counts are read from the running backend—not maintained as a static diagram.</p></div><div><button className="secondary" onClick={() => model.data && initialize(model.data)}>Reset layout</button><button className="secondary" onClick={() => setRunning(value => !value)}>{running ? 'Pause physics' : 'Resume physics'}</button><button onClick={() => model.refetch()} disabled={model.isFetching}>{model.isFetching ? 'Refreshing…' : 'Refresh model'}</button></div></section>{model.isLoading ? <State text="Reading the live application model…"/> : model.error ? <State text={model.error.message}/> : model.data && <div className="data-model-layout"><section className="model-canvas"><div className="model-canvas-head"><span>{model.data.nodes.length} tables · {model.data.links.length} relationships</span><small>{model.data.database} · generated {new Intl.DateTimeFormat(undefined, {dateStyle: 'medium', timeStyle: 'short'}).format(new Date(model.data.generated_at))}</small></div><svg ref={svgRef} viewBox="0 0 1100 650" role="img" aria-label="Force-directed live database relationship model" onPointerMove={moveDragged} onPointerUp={() => setDragging('')} onPointerLeave={() => setDragging('')}><defs><marker id="model-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs>{model.data.links.map((link, index) => { const source = positions[link.source], target = positions[link.target]; return source && target ? <line className="model-link" x1={source.x} y1={source.y} x2={target.x} y2={target.y} markerEnd="url(#model-arrow)" key={`${link.source}-${link.source_column}-${index}`}><title>{link.source}.{link.source_column} → {link.target}.{link.target_column}</title></line> : null })}{model.data.nodes.map(node => { const point = positions[node.id]; if (!point) return null; const selectedNode = selectedId === node.id; return <g className={`model-node ${selectedNode ? 'selected' : ''}`} transform={`translate(${point.x - 75} ${point.y - 25})`} key={node.id} onPointerDown={event => { event.currentTarget.setPointerCapture(event.pointerId); setDragging(node.id); setSelectedId(node.id) }} onClick={() => setSelectedId(node.id)}><rect width="150" height="50" rx="9"/><text x="12" y="21">{node.id}</text><text className="model-node-count" x="12" y="38">{node.row_count.toLocaleString()} rows · {node.columns.length} fields</text></g>})}</svg><p>Drag tables to reshape the model. Relationship arrows flow from each foreign-key table toward the referenced parent table.</p></section><aside className="model-inspector">{selected ? <><div><span className="step">SELECTED TABLE</span><h2>{selected.id}</h2><p>{selected.row_count.toLocaleString()} current rows</p></div><div className="model-columns">{selected.columns.map(column => <div key={column.name}><span>{column.primary_key ? 'PK' : column.nullable ? '○' : '●'}</span><strong>{column.name}</strong><small>{column.type}</small></div>)}</div><section><strong>Relationships</strong>{model.data.links.filter(link => link.source === selected.id || link.target === selected.id).map((link, index) => <p key={index}><code>{link.source}.{link.source_column}</code><span>→</span><code>{link.target}.{link.target_column}</code></p>)}</section></> : <State text="Select a table to inspect its columns."/>}</aside></div>}</>
}

function GrafanaIntegrationDocument({configured}: {configured?: boolean}) {
  const endpoint = 'http://localhost:8000/api/v1/integrations/grafana/traceability/cards/10732'
  return <><PageHeader eyebrow="DOCUMENTATION · INTEGRATION" title="Grafana Integration" subtitle="Load the complete calculated Traceability view with only a project ID." configured={configured}/><section className="grafana-guide"><div className="api-overview"><div><span className="step">COMPLETE TRACEABILITY EXPORT</span><h2>One project ID, one complete JSON response</h2><p>The endpoint reads the saved level and grid configurations, performs the same card calculations as Traceability, and returns nested cards, metrics, dates, bottom-level work items, configured Jira fields, and Grafana node/edge frames.</p></div><code className="grafana-endpoint">GET /api/v1/integrations/grafana/traceability/{'{project_id}'}</code></div><div className="guide-note" role="note"><strong>No additional request configuration:</strong> Pass only the Jira project ID. Level fields, captions and optional grid fields are resolved from the project’s saved application configuration.</div><div className="grafana-steps"><article><b>1</b><div><h2>Prepare the application</h2><p>Discover Jira metadata, activate the project, run a sync, and save its Traceability Level Config and Traceability Grid Config. These settings define the exported hierarchy and work-item columns.</p></div></article><article><b>2</b><div><h2>Add the Grafana data source</h2><p>Configure a REST/JSON-compatible data source with base URL <code>http://localhost:8000</code>, or the network address through which the Grafana server can reach FastAPI.</p></div></article><article><b>3</b><div><h2>Query with only the project ID</h2><p>Request <code>/api/v1/integrations/grafana/traceability/10732</code>. No field IDs, filters, level list, captions or calculation parameters are required.</p></div></article><article><b>4</b><div><h2>Choose the JSON dataset per panel</h2><p>Use <code>traceability.flat_cards</code> for a card metrics table, <code>traceability.cards</code> for the nested view, leaf <code>work_items</code> for grids, and <code>nodes</code>/<code>edges</code> for a Node graph.</p></div></article><article><b>5</b><div><h2>Set refresh and validate</h2><p>Refresh after the application’s Jira sync. Compare <code>summary.issue_count</code>, <code>summary.card_count</code> and <code>sync_version</code> when validating the Grafana dashboard.</p></div></article></div><section className="api-example"><span className="step">COMPLETE EXPORT REQUEST</span><h2>SDHI / Jira project 10732</h2><pre>{`curl "${endpoint}"`}</pre></section><section className="grafana-schema"><div><span className="step">RESPONSE DATASETS</span><h2>Direct Grafana mappings</h2></div><div className="grafana-schema-grid"><article><strong>configuration</strong><p>Saved levels, captions, mandatory grid columns and configured optional Jira fields.</p></article><article><strong>traceability.cards</strong><p>Complete nested card hierarchy. Every card includes its path, filter, issue count, warnings and calculated metrics.</p></article><article><strong>traceability.flat_cards</strong><p>One flat record per card for Grafana Table, Stat, Bar gauge and transformation workflows.</p></article><article><strong>work_items</strong><p>Bottom-level grid rows with key, summary, type, status, baseline/revised due dates and configured fields.</p></article><article><strong>nodes / edges</strong><p>Ready-to-map Node graph frames representing every exported card and parent-child connection.</p></article><article><strong>summary / sync_version</strong><p>Dataset totals and freshness indicators for dashboard validation.</p></article></div></section><section className="guide-troubleshooting"><span className="step">TROUBLESHOOTING</span><h2>If the Grafana data is incomplete</h2><ol><li>Call the endpoint directly and confirm it returns HTTP 200.</li><li>Verify the project is active and has synchronized issues.</li><li>Confirm both Traceability Level Config and Traceability Grid Config are saved for the project.</li><li>Run a Full sync after adding Jira fields to the configuration.</li><li>Compare the response <code>sync_version</code> after synchronization.</li></ol></section></section></>
}

function Overview({summary, groups, projects}: {summary?: Awaited<ReturnType<typeof api.summary>>; groups?: {value: unknown; label: string; issue_count: number}[]; projects: Project[]}) {
  const projectSummaries = useQueries({queries: projects.map(project => ({queryKey: ['summary', [project.jira_project_id]], queryFn: () => api.summary([project.jira_project_id])}))})
  const projectStatuses = useQueries({queries: projects.map(project => ({queryKey: ['status-groups', [project.jira_project_id]], queryFn: () => api.groupBy('status_id', [project.jira_project_id])}))})
  const plans = useQuery({queryKey: ['project-plans'], queryFn: api.projectPlans})
  const planByProject = new Map((plans.data?.items ?? []).map(plan => [plan.project_id, plan]))
  return <div className="overview-sections"><PortfolioSnapshot title="All active projects" eyebrow="LIVE PORTFOLIO" detail={`${projects.length} active ${projects.length === 1 ? 'project' : 'projects'}`} summary={summary} groups={groups}/>{projects.length ? <section className="project-overviews"><div className="overview-section-title"><div><span className="step">PROJECT BREAKDOWN</span><h2>Individual project snapshots</h2></div><span>{projects.length} cards · select one to open WBS</span></div><div className="project-overview-grid">{projects.map((project, index) => <Link className="project-snapshot-link" to={`/wbs?project=${encodeURIComponent(project.jira_project_id)}`} aria-label={`Open WBS flow for ${project.name}`} key={project.jira_project_id}><PortfolioSnapshot title={project.name} eyebrow={project.key} detail={`Jira ID ${project.jira_project_id}`} summary={projectSummaries[index]?.data} groups={projectStatuses[index]?.data?.groups} loading={projectSummaries[index]?.isLoading || projectStatuses[index]?.isLoading} compact plan={planByProject.get(project.jira_project_id)}/><span className="open-wbs-cue">Open WBS flow <i aria-hidden="true">→</i></span></Link>)}</div></section> : <State text="Activate at least one Jira project to display portfolio cards."/>}</div>
}

function PortfolioSnapshot({title, eyebrow, detail, summary, groups, loading, compact = false, plan}: {title: string; eyebrow: string; detail: string; summary?: Awaited<ReturnType<typeof api.summary>>; groups?: {value: unknown; label: string; issue_count: number}[]; loading?: boolean; compact?: boolean; plan?: ProjectPlan}) {
  const displayDate = (value: string | null | undefined) => value ? new Intl.DateTimeFormat(undefined, {dateStyle: 'medium', timeZone: 'UTC'}).format(new Date(`${value}T00:00:00Z`)) : 'Not defined'
  return <section className={`analytics-panel ${compact ? 'project-analytics' : 'portfolio-total'}`}><div className="cardhead"><div><span className="step">{eyebrow}</span><h2>{title}</h2><small className="snapshot-detail">{detail}</small></div><span>Sync version {summary?.sync_version ?? '—'}</span></div>{compact && <div className="project-plan-strip"><span><small>Project start</small><strong>{displayDate(plan?.start_date)}</strong></span><span><small>Baseline 1 end</small><strong>{displayDate(plan?.baseline_date)}</strong></span><span><small>Latest baseline {plan?.latest_baseline_version ? `· B${plan.latest_baseline_version}` : ''}</small><strong>{displayDate(plan?.latest_baseline_date)}</strong></span><span><small>Project Status (RAG)</small><strong className={`rag-status rag-${(plan?.project_status ?? "unset").toLowerCase()}`}>{plan?.project_status ?? "Not set"}</strong></span><span className="governance-support"><small>Support Required from Management</small><strong>{plan?.management_support?.trim() || "None specified"}</strong></span></div>}{loading ? <State text="Calculating project metrics…"/> : <><div className="kpis">{summary?.metrics.map(metric => <div className="kpi" key={metric.metric_id}><small>{metric.metric_id.replaceAll('_', ' ')}</small><strong>{metric.unit === 'ratio' ? metric.value == null ? '—' : `${Math.round(metric.value * 100)}%` : metric.value ?? '—'}</strong><span>{metric.numerator} / {metric.denominator}</span></div>) ?? <State text="Run a sync to calculate portfolio metrics."/>}</div>{groups?.length ? <div className="distribution"><b>Status distribution</b><div>{groups.slice(0, compact ? 5 : 8).map(group => <span key={String(group.value)}>{group.label} <strong>{group.issue_count}</strong></span>)}</div></div> : null}</>}</section>
}

function LevelPath({captions}: {captions: string[]}) {
  const icons = ['◈', '◉', '▦', '◇', '●', '◆', '◎', '▤']
  return <div className="level-path" aria-label={`Configured path: ${captions.join(', ')}`}>{captions.map((caption, index) => <div className="level-path-segment" key={`${caption}-${index}`}><span className="level-path-node"><i aria-hidden="true">{icons[index % icons.length]}</i><small>Level {index + 1}</small><strong>{caption}</strong></span>{index < captions.length - 1 && <span className="level-path-connector" aria-hidden="true"><b/><i>›</i></span>}</div>)}</div>
}

function groupingChoices(fields: Field[]) { return [
    {id: 'status_id', name: 'Status'}, {id: 'issue_type_id', name: 'Issue type'}, {id: 'assignee', name: 'Assignee'},
    ...fields.filter(field => field.jira_field_id === 'labels' || field.is_custom).map(field => ({id: field.jira_field_id, name: field.name})),
  ].filter((choice, index, all) => all.findIndex(item => item.id === choice.id) === index) }

function sprintGroupingChoices(fields: Field[]) { return [
  {id: 'status_id', name: 'Status'}, {id: 'issue_type_id', name: 'Issue type'}, {id: 'assignee', name: 'Assignee'},
  ...fields.filter(field => !new Set(['summary', 'project', 'issuetype', 'status', 'parent', 'assignee', 'reporter', 'created', 'updated', 'duedate', 'resolutiondate']).has(field.jira_field_id)).map(field => ({id: field.jira_field_id, name: field.name})),
].filter((choice, index, all) => all.findIndex(item => item.id === choice.id) === index) }

function CardViewPage({projects, fields, configured}: {projects: Project[]; fields: Field[]; configured?: boolean}) {
  const fallbackProject = projects.find(project => project.active) ?? projects[0]
  const [projectId, setProjectId] = useState('')
  useEffect(() => { if (!projectId && fallbackProject) setProjectId(fallbackProject.jira_project_id) }, [projectId, fallbackProject])
  const project = projects.find(item => item.jira_project_id === projectId)
  const config = useQuery({queryKey: ['traceability-config', projectId], queryFn: () => api.traceabilityConfig(projectId), enabled: !!projectId})
  const groupingFields = config.data?.grouping_fields ?? ['labels', 'status_id', 'issue_type_id']
  const choices = groupingChoices(fields)
  const levelCaptions = groupingFields.map((field, index) => config.data?.level_captions[index]?.trim() || choices.find(choice => choice.id === field)?.name || field)
  return <><PageHeader eyebrow="PORTFOLIO VIEW" title="Traceability" subtitle={project ? `${project.key} · ${groupingFields.length} grouping levels` : 'Select a project'} configured={configured}/><section className="project-picker"><label>Project <select aria-label="Traceability project" value={projectId} onChange={event => setProjectId(event.target.value)}><option value="" disabled>Select a project</option>{projects.map(item => <option key={item.jira_project_id} value={item.jira_project_id}>{item.key} · {item.name}</option>)}</select></label><span>{config.data?.persisted ? 'Saved traceability configuration' : 'Using default grouping'}</span></section>{projectId && !config.isLoading ? <section className="card-browser" key={`${projectId}-${groupingFields.join('|')}-${levelCaptions.join('|')}`}><div className="cardhead path-cardhead"><div><span className="step">NESTED CARD PATH</span><LevelPath captions={levelCaptions}/></div><span>Select a card to open the next level</span></div><CardGroupingBranch projectId={projectId} fields={groupingFields} captions={levelCaptions} choices={choices} level={0} filters={[]}/></section> : <State text="Loading traceability configuration…"/>}</>
}

const mandatoryGridColumns = ['Key', 'Summary', 'Issue type', 'Baseline due', 'Revised due', 'Status']

function SprintViewConfiguration({projects, configured, onNotice}: {projects: Project[]; configured?: boolean; onNotice: (message: string) => void}) {
  const queryClient = useQueryClient()
  const fallbackProject = projects.find(project => project.active) ?? projects[0]
  const [projectId, setProjectId] = useState('')
  const [levels, setLevels] = useState<string[]>([])
  const [captions, setCaptions] = useState<string[]>([])
  useEffect(() => { if (!projectId && fallbackProject) setProjectId(fallbackProject.jira_project_id) }, [projectId, fallbackProject])
  const projectFields = useQuery({queryKey: ['project-grid-fields', projectId], queryFn: () => api.gridFields(projectId), enabled: Boolean(projectId)})
  const config = useQuery({queryKey: ['sprint-view-config', projectId], queryFn: () => api.sprintViewConfig(projectId), enabled: Boolean(projectId)})
  useEffect(() => { if (config.data) { setLevels(config.data.grouping_fields); setCaptions(config.data.grouping_fields.map((_, index) => config.data?.level_captions[index] ?? '')) } }, [config.data])
  const choices = sprintGroupingChoices(projectFields.data?.items ?? [])
  const save = useMutation({mutationFn: () => api.saveSprintViewConfig(projectId, levels, captions), onSuccess: data => { queryClient.setQueryData(['sprint-view-config', projectId], data); onNotice(`Saved ${levels.length} Sprint View levels for ${projects.find(project => project.jira_project_id === projectId)?.key ?? projectId}.`) }, onError: error => onNotice(error.message)})
  const addLevel = () => { const next = choices.find(choice => !levels.includes(choice.id)); if (next) { setLevels(current => [...current, next.id]); setCaptions(current => [...current, '']) } }
  const removeLevel = (index: number) => { setLevels(current => current.filter((_, position) => position !== index)); setCaptions(current => current.filter((_, position) => position !== index)) }
  return <><PageHeader eyebrow="APP SETTING · CONFIGURATION" title="Sprint View configuration" subtitle="Define project-specific execution grouping and captions." configured={configured}/><section className="trace-config"><div className="trace-project"><label>Project<select aria-label="Sprint View configuration project" value={projectId} onChange={event => { setProjectId(event.target.value); setLevels([]); setCaptions([]) }}><option value="" disabled>Select a project</option>{projects.map(project => <option key={project.jira_project_id} value={project.jira_project_id}>{project.key} · {project.name}</option>)}</select></label><p>Fields are derived from Jira metadata present for the selected project. Configure any number of nested grouping levels.</p></div>{projectFields.isLoading || config.isLoading ? <State text="Loading applicable Jira metadata…"/> : <div className="level-editor">{levels.map((field, index) => <div className="level-edit" key={index}><span>{index + 1}</span><label><span className="sr-only">Sprint grouping field for level {index + 1}</span><select value={field} onChange={event => setLevels(current => current.map((item, position) => position === index ? event.target.value : item))}>{choices.map(choice => <option key={choice.id} value={choice.id}>{choice.name}</option>)}</select></label><label className="caption-input"><span>Card caption</span><input maxLength={100} value={captions[index] ?? ''} placeholder={choices.find(choice => choice.id === field)?.name ?? field} onChange={event => setCaptions(current => current.map((item, position) => position === index ? event.target.value : item))}/></label>{levels.length > 1 && <button className="secondary" aria-label={`Remove sprint level ${index + 1}`} onClick={() => removeLevel(index)}>Remove</button>}</div>)}</div>}<div className="trace-actions"><button className="secondary" disabled={!choices.some(choice => !levels.includes(choice.id))} onClick={addLevel}>Add grouping level</button><button disabled={!projectId || !levels.length || save.isPending} onClick={() => save.mutate()}>{save.isPending ? 'Saving…' : 'Save Sprint View configuration'}</button></div></section></>
}

function GridConfiguration({scope, projects, configured, onNotice}: {scope: 'traceability' | 'sprint'; projects: Project[]; configured?: boolean; onNotice: (message: string) => void}) {
  const queryClient = useQueryClient()
  const fallbackProject = projects.find(project => project.active) ?? projects[0]
  const [projectId, setProjectId] = useState('')
  const [selectedFields, setSelectedFields] = useState<string[]>([])
  const [fieldToAdd, setFieldToAdd] = useState('')
  useEffect(() => { if (!projectId && fallbackProject) setProjectId(fallbackProject.jira_project_id) }, [projectId, fallbackProject])
  const project = projects.find(item => item.jira_project_id === projectId)
  const config = useQuery({queryKey: [`${scope}-grid-config`, projectId], queryFn: () => scope === 'sprint' ? api.sprintGridConfig(projectId) : api.gridConfig(projectId), enabled: Boolean(projectId)})
  const applicableFields = useQuery({queryKey: ['project-grid-fields', projectId], queryFn: () => api.gridFields(projectId), enabled: Boolean(projectId)})
  useEffect(() => { if (config.data) setSelectedFields(config.data.optional_fields.map(field => field.field_id)) }, [config.data])
  const save = useMutation({mutationFn: () => scope === 'sprint' ? api.saveSprintGridConfig(projectId, selectedFields) : api.saveGridConfig(projectId, selectedFields), onSuccess: () => { onNotice(`${scope === 'sprint' ? 'Sprint' : 'Traceability'} Grid configuration saved.`); queryClient.invalidateQueries({queryKey: [`${scope}-grid-config`, projectId]}); queryClient.invalidateQueries({queryKey: ['card-result-issues']}); queryClient.invalidateQueries({queryKey: ['card-result-epics']}) }, onError: error => onNotice(error.message)})
  const excluded = new Set(['key', 'summary', 'issuetype', 'issue_type_id', 'status', 'status_id', 'duedate'])
  const available = (applicableFields.data?.items ?? []).filter(field => !excluded.has(field.jira_field_id) && !selectedFields.includes(field.jira_field_id))
  const fieldById = new Map((applicableFields.data?.items ?? []).map(field => [field.jira_field_id, field]))
  const move = (index: number, offset: number) => setSelectedFields(current => { const next = [...current]; const target = index + offset; if (target < 0 || target >= next.length) return current; [next[index], next[target]] = [next[target], next[index]]; return next })
  const add = () => { if (fieldToAdd) { setSelectedFields(current => [...current, fieldToAdd]); setFieldToAdd('') } }
  const viewName = scope === 'sprint' ? 'Sprint Grid' : 'Traceability Grid'
  return <><PageHeader eyebrow="APP SETTING · CONFIGURATION · GRID" title={`${viewName} configuration`} subtitle={project ? `${project.key} · Configure ${viewName} work-item columns` : 'Select a project'} configured={configured}/><section className="project-picker"><label>Project <select aria-label={`${viewName} configuration project`} value={projectId} onChange={event => { setProjectId(event.target.value); setSelectedFields([]); setFieldToAdd('') }}><option value="" disabled>Select a project</option>{projects.map(item => <option key={item.jira_project_id} value={item.jira_project_id}>{item.key} · {item.name}</option>)}</select></label><span>Configuration applies only to this project and view</span></section><section className="grid-config"><div className="cardhead"><div><span className="step">MANDATORY COLUMNS</span><h2>Always displayed</h2></div><span>{mandatoryGridColumns.length} columns</span></div><div className="mandatory-columns">{mandatoryGridColumns.map((column, index) => <span key={column}><b>{index + 1}</b>{column}</span>)}</div><div className="grid-field-builder"><div><span className="step">OPTIONAL JIRA FIELDS</span><h2>{viewName} project columns</h2><p>Only fields applicable to the selected project are available. Newly selected fields may require a Jira sync before values appear.</p></div><div className="grid-field-add"><select aria-label="Applicable Jira field" value={fieldToAdd} onChange={event => setFieldToAdd(event.target.value)}><option value="">Select a standard or custom field…</option>{available.map(field => <option value={field.jira_field_id} key={field.jira_field_id}>{field.name} · {field.is_custom ? 'Custom' : 'Standard'}</option>)}</select><button disabled={!fieldToAdd} onClick={add}>Add column</button></div></div>{config.isLoading || applicableFields.isLoading ? <State text="Loading project fields…"/> : <div className="selected-grid-fields">{selectedFields.length ? selectedFields.map((fieldId, index) => { const field = fieldById.get(fieldId); return <div className="selected-grid-field" key={fieldId}><span className="field-order">{mandatoryGridColumns.length + index + 1}</span><div><strong>{field?.name ?? fieldId}</strong><small>{fieldId} · {field?.is_custom ? 'Custom field' : 'Standard field'}</small></div><div className="field-actions"><button className="secondary" disabled={index === 0} onClick={() => move(index, -1)} aria-label={`Move ${field?.name ?? fieldId} up`}>↑</button><button className="secondary" disabled={index === selectedFields.length - 1} onClick={() => move(index, 1)} aria-label={`Move ${field?.name ?? fieldId} down`}>↓</button><button className="remove-field" onClick={() => setSelectedFields(current => current.filter(value => value !== fieldId))}>Remove</button></div></div>}) : <State text="No optional columns selected."/>}</div>}<div className="trace-actions"><span>{selectedFields.length} optional columns</span><button disabled={!projectId || save.isPending} onClick={() => save.mutate()}>{save.isPending ? 'Saving…' : `Save ${viewName} configuration`}</button></div></section></>
}

function WbsViewPage({projects, configured}: {projects: Project[]; configured?: boolean}) {
  const [searchParams] = useSearchParams()
  const fallbackProject = projects.find(project => project.active) ?? projects[0]
  const requestedProjectId = searchParams.get('project') ?? ''
  const [projectId, setProjectId] = useState(requestedProjectId)
  useEffect(() => { if (requestedProjectId && projects.some(project => project.jira_project_id === requestedProjectId)) setProjectId(requestedProjectId); else if (!projectId && fallbackProject) setProjectId(fallbackProject.jira_project_id) }, [requestedProjectId, projectId, fallbackProject, projects])
  const project = projects.find(item => item.jira_project_id === projectId)
  const flow = useQuery({queryKey: ['wbs-flow', projectId], queryFn: () => api.wbsFlow(projectId), enabled: Boolean(projectId)})
  return <><PageHeader eyebrow="PORTFOLIO VIEW" title="WBS flow" subtitle={project ? `${project.key} · Traceability flow across configured levels` : 'Select a project'} configured={configured}/><section className="project-picker"><label>Project <select aria-label="WBS project" value={projectId} onChange={event => setProjectId(event.target.value)}><option value="" disabled>Select a project</option>{projects.map(item => <option key={item.jira_project_id} value={item.jira_project_id}>{item.key} · {item.name}</option>)}</select></label><span>{flow.data ? `${flow.data.issue_count} work items · Sync version ${flow.data.sync_version}` : 'Loading flow'}</span></section>{flow.isLoading ? <State text="Building WBS flow…"/> : flow.error ? <State text={flow.error.message}/> : flow.data ? <SankeyPlot flow={flow.data}/> : null}</>
}

function SprintViewPage({projects, configured}: {projects: Project[]; configured?: boolean}) {
  const fallbackProject = projects.find(project => project.active) ?? projects[0]
  const [projectId, setProjectId] = useState('')
  useEffect(() => { if (!projectId && fallbackProject) setProjectId(fallbackProject.jira_project_id) }, [projectId, fallbackProject])
  const project = projects.find(item => item.jira_project_id === projectId)
  const config = useQuery({queryKey: ['sprint-view-config', projectId], queryFn: () => api.sprintViewConfig(projectId), enabled: Boolean(projectId)})
  const projectFields = useQuery({queryKey: ['project-grid-fields', projectId], queryFn: () => api.gridFields(projectId), enabled: Boolean(projectId)})
  const groupingFields = config.data?.grouping_fields ?? []
  const choices = sprintGroupingChoices(projectFields.data?.items ?? [])
  const captions = groupingFields.map((field, index) => config.data?.level_captions[index]?.trim() || choices.find(choice => choice.id === field)?.name || field)
  return <><PageHeader eyebrow="EXECUTION VIEW" title="Sprint View" subtitle={project ? `${project.key} · ${groupingFields.length} configured execution levels` : 'Select a project'} configured={configured}/><section className="project-picker"><label>Project <select aria-label="Sprint project" value={projectId} onChange={event => setProjectId(event.target.value)}><option value="" disabled>Select a project</option>{projects.map(item => <option key={item.jira_project_id} value={item.jira_project_id}>{item.key} · {item.name}</option>)}</select></label><span>{config.data?.persisted ? 'Saved Sprint View configuration' : 'Using metadata-driven default grouping'}</span></section>{config.isLoading || projectFields.isLoading ? <State text="Loading Sprint View configuration…"/> : groupingFields.length ? <section className="card-browser" key={`${projectId}-${groupingFields.join('|')}-${captions.join('|')}`}><div className="cardhead path-cardhead"><div><span className="step">SPRINT EXECUTION PATH</span><LevelPath captions={captions}/></div><span>Select a card to open the next execution level</span></div><CardGroupingBranch projectId={projectId} fields={groupingFields} captions={captions} choices={choices} level={0} filters={[]} gridScope="sprint"/></section> : <State text="Configure at least one Sprint View grouping level."/>}</>
}

function SankeyPlot({flow}: {flow: WbsFlow}) {
  const [selected, setSelected] = useState<string | null>(null)
  const [selectedLeaf, setSelectedLeaf] = useState<WbsFlow['nodes'][number] | null>(null)
  useEffect(() => {
    const close = (event: KeyboardEvent) => { if (event.key === 'Escape') setSelectedLeaf(null) }
    window.addEventListener('keydown', close)
    return () => window.removeEventListener('keydown', close)
  }, [])
  const width = 1200
  const grouped = flow.levels.map((_, level) => flow.nodes.filter(node => node.level === level).sort((a, b) => b.value - a.value))
  const maxNodes = Math.max(1, ...grouped.map(nodes => nodes.length))
  const height = Math.max(520, maxNodes * 58 + 100)
  const positions = new Map<string, {x: number; y: number; h: number}>()
  grouped.forEach((nodes, level) => nodes.forEach((node, index) => {
    const x = 90 + level * ((width - 180) / Math.max(1, flow.levels.length - 1))
    const y = 75 + index * ((height - 120) / Math.max(1, nodes.length))
    const h = Math.max(14, Math.min(38, 12 + (node.value / Math.max(1, flow.issue_count)) * 90))
    positions.set(node.id, {x, y, h})
  }))
  const connected = new Set<string>()
  if (selected) flow.links.forEach(link => { if (link.source === selected) connected.add(link.target); if (link.target === selected) connected.add(link.source) })
  const maxLink = Math.max(1, ...flow.links.map(link => link.value))
  const lastLevel = flow.levels.length - 1
  const leafField = flow.levels[lastLevel]?.field_id
  const nodeValue = (node: WbsFlow['nodes'][number]) => node.id.slice(node.id.indexOf(':') + 1)
  const leafFilter = selectedLeaf && leafField ? (() => {
    const value = nodeValue(selectedLeaf)
    if (value === '__null__') return {field_id: leafField, operator: 'is_null', value: true}
    if (value !== '__other__') return {field_id: leafField, operator: 'eq', value}
    const leafNodes = flow.nodes.filter(node => node.level === lastLevel)
    const regularValues = leafNodes.map(nodeValue).filter(item => item !== '__null__' && item !== '__other__')
    const remainder = {field_id: leafField, operator: 'not_in', value: regularValues}
    return leafNodes.some(node => nodeValue(node) === '__null__') ? remainder : {or: [remainder, {field_id: leafField, operator: 'is_null', value: true}]}
  })() : null
  const activateNode = (node: WbsFlow['nodes'][number]) => {
    setSelected(current => current === node.id ? null : node.id)
    if (node.level === lastLevel) setSelectedLeaf(node)
  }
  return <section className="wbs-panel"><div className="wbs-heading path-cardhead"><div><span className="step">CONFIGURED TRACEABILITY FLOW</span><LevelPath captions={flow.levels.map(level => level.caption)}/></div><span>Click a terminal node to open its work-item grid</span></div><div className="sankey-wrap"><svg className="sankey" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`WBS Sankey flow for ${flow.issue_count} Jira work items`}><defs><linearGradient id="flow-gradient" x1="0" x2="1"><stop offset="0" stopColor="#29469a"/><stop offset=".55" stopColor="#7188ce"/><stop offset="1" stopColor="#d71920"/></linearGradient></defs>{flow.levels.map((level, index) => <text className="sankey-level" x={90 + index * ((width - 180) / Math.max(1, flow.levels.length - 1))} y="28" textAnchor="middle" key={level.field_id}>{level.caption}</text>)}<g className="sankey-links">{flow.links.map((link, index) => { const source = positions.get(link.source); const target = positions.get(link.target); if (!source || !target) return null; const active = !selected || link.source === selected || link.target === selected || (connected.has(link.source) && connected.has(link.target)); const bend = (target.x - source.x) * .48; return <path className={active ? 'active' : 'dim'} d={`M ${source.x + 10} ${source.y + source.h / 2} C ${source.x + bend} ${source.y + source.h / 2}, ${target.x - bend} ${target.y + target.h / 2}, ${target.x - 10} ${target.y + target.h / 2}`} strokeWidth={Math.max(1.5, (link.value / maxLink) * 18)} key={`${link.source}-${link.target}-${index}`}><title>{link.value} work items</title></path>})}</g><g className="sankey-nodes">{flow.nodes.map(node => { const position = positions.get(node.id); if (!position) return null; const active = !selected || node.id === selected || connected.has(node.id); const last = node.level === lastLevel; return <g className={active ? 'active' : 'dim'} role="button" tabIndex={0} aria-label={`${node.label}, ${node.value} work items${last ? ', open grid' : ''}`} onClick={() => activateNode(node)} onKeyDown={event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); activateNode(node) } }} key={node.id}><rect x={position.x - 10} y={position.y} width="20" height={position.h} rx="7"/><circle cx={position.x} cy={position.y + position.h / 2} r="3"/><text x={last ? position.x - 18 : position.x + 18} y={position.y + position.h / 2 - 2} textAnchor={last ? 'end' : 'start'}>{node.label}</text><text className="sankey-value" x={last ? position.x - 18 : position.x + 18} y={position.y + position.h / 2 + 12} textAnchor={last ? 'end' : 'start'}>{node.value} work items</text></g>})}</g></svg></div>{selected && <button className="secondary wbs-reset" onClick={() => setSelected(null)}>Show all flows</button>}{selectedLeaf && leafFilter && <div className="wbs-modal-backdrop" onMouseDown={() => setSelectedLeaf(null)}><section className="wbs-modal" role="dialog" aria-modal="true" aria-labelledby="wbs-modal-title" onMouseDown={event => event.stopPropagation()}><div className="wbs-modal-head"><div><span className="step">{flow.levels[lastLevel].caption} · WORK ITEMS</span><h2 id="wbs-modal-title">{selectedLeaf.label}</h2></div><button className="wbs-modal-close" onClick={() => setSelectedLeaf(null)} aria-label="Close WBS work-item grid">×</button></div><CardResults projectId={flow.project_id} filter={leafFilter} direct={flow.levels.some(level => level.field_id === 'issue_type_id')} groupLabel={selectedLeaf.label}/></section></div>}</section>
}

type CardMetricsData = {task_count: number; in_progress_count: number; baseline_delayed_count: number; on_track_count: number; delayed_count: number; no_due_date_count: number; baseline_due_date: string | null; latest_due_date: string | null; next_group_count: number}

function cardDate(value: string | null) {
  return value ? new Intl.DateTimeFormat(undefined, {day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC'}).format(new Date(value)) : 'Not set'
}

function CardMetrics({group, showNext}: {group: CardMetricsData; showNext: boolean}) {
  const rows = [
    {icon: '▦', label: 'Tasks', value: group.task_count, tone: 'tasks', hint: 'Bottom-level work items'},
    {icon: '◔', label: 'In progress', value: group.in_progress_count, tone: 'progress', hint: 'Tasks in Jira status category In Progress'},
    {icon: '◆', label: 'Baseline delayed', value: group.baseline_delayed_count, tone: 'baseline', hint: 'Open tasks past their first Jira due date'},
    {icon: '✓', label: 'Revised on track', value: group.on_track_count, tone: 'track', hint: 'Open tasks whose current Jira due date has not passed'},
    {icon: '!', label: 'Revised delayed', value: group.delayed_count, tone: 'delay', hint: 'Open tasks past their current Jira due date'},
    {icon: '∅', label: 'No due date', value: group.no_due_date_count, tone: 'missing', hint: 'Open tasks without a Jira due date'},
    ...(showNext ? [{icon: '⇲', label: 'Next-level groups', value: group.next_group_count, tone: 'groups', hint: 'Distinct groups at the next configured level'}] : []),
  ]
  return <><div className="card-date-strip" aria-label="Card due dates"><span title="Latest first-assigned due date across bottom-level tasks"><i aria-hidden="true">◆</i><small>Baseline due</small><b>{cardDate(group.baseline_due_date)}</b></span><span title="Latest current Jira due date across bottom-level tasks"><i aria-hidden="true">↻</i><small>Latest Jira due</small><b>{cardDate(group.latest_due_date)}</b></span></div><table className="card-metrics" aria-label="Card metrics"><tbody>{rows.map(row => <tr className={`metric-${row.tone}`} title={row.hint} key={row.label}><td><span className="metric-icon" aria-hidden="true">{row.icon}</span>{row.label}</td><td>{row.value}</td></tr>)}</tbody></table></>
}

type GridScope = 'traceability' | 'sprint'

function CardGroupingBranch({projectId, fields, captions, choices, level, filters, gridScope = 'traceability'}: {projectId: string; fields: string[]; captions: string[]; choices: {id: string; name: string}[]; level: number; filters: Record<string, unknown>[]; gridScope?: GridScope}) {
  const [selected, setSelected] = useState<Group | null>(null)
  const field = fields[level]
  const filter = combineFilters(filters)
  const nextField = fields[level + 1]
  const groups = useQuery({queryKey: ['card-groups', projectId, level, field, nextField, filter], queryFn: () => api.cardGroups(field, nextField, [projectId], filter ?? undefined)})
  const fieldName = captions[level] || choices.find(choice => choice.id === field)?.name || field
  if (groups.isLoading) return <State text={`Loading ${fieldName} cards…`}/>
  if (groups.error) return <State text={groups.error.message}/>
  return <div className="card-level"><div className="card-level-title"><span>Level {level + 1}</span><strong>{fieldName}</strong></div><div className="trace-card-grid">{groups.data?.groups.map(group => { const open = selected?.value === group.value; const muted = selected !== null && !open; const empty = group.task_count === 0; const nextFilters = [...filters, groupFilter(field, group)]; return <article className={`trace-card ${open ? 'open' : ''} ${muted ? 'muted' : ''} ${empty ? 'empty-card' : ''}`} key={`${field}-${String(group.value)}`}><button className="trace-card-button" onClick={() => setSelected(open ? null : group)} aria-expanded={open}><span>{group.label}</span><strong>{group.issue_count}</strong><CardMetrics group={group} showNext={Boolean(nextField)}/><small>{level === fields.length - 1 ? 'View work items' : `Open ${captions[level + 1] || `level ${level + 2}`}`}</small></button>{open && <div className="trace-card-children">{level === fields.length - 1 ? <CardResults projectId={projectId} filter={combineFilters(nextFilters)!} direct={fields.includes('issue_type_id')} groupLabel={group.label} gridScope={gridScope}/> : <CardGroupingBranch projectId={projectId} fields={fields} captions={captions} choices={choices} level={level + 1} filters={nextFilters} gridScope={gridScope}/>}</div>}</article>})}</div>{groups.data?.non_additive && <p className="group-warning">Multi-value groups can overlap.</p>}</div>
}

function CardResults({projectId, filter, direct, groupLabel, gridScope = 'traceability'}: {projectId: string; filter: Record<string, unknown>; direct: boolean; groupLabel: string; gridScope?: GridScope}) {
  type SortField = 'key' | 'summary' | 'type' | 'baseline' | 'revised' | 'status'
  const [sortField, setSortField] = useState<SortField>('key')
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc')
  const [search, setSearch] = useState('')
  const [issueType, setIssueType] = useState('')
  const [status, setStatus] = useState('')
  const [dueFilter, setDueFilter] = useState('')
  const [metadataIssueKey, setMetadataIssueKey] = useState<string | null>(null)
  const epics = useQuery({queryKey: ['card-result-epics', projectId, filter], queryFn: () => api.epicsByFilter([projectId], filter), enabled: !direct})
  const issues = useQuery({queryKey: ['card-result-issues', projectId, filter], queryFn: () => api.issuesByFilter([projectId], filter), enabled: direct})
  const liveMetadata = useQuery({queryKey: ['live-issue-metadata', metadataIssueKey], queryFn: () => api.issueMetadata(metadataIssueKey!), enabled: Boolean(metadataIssueKey), staleTime: 0, gcTime: 0})
  const gridConfig = useQuery({queryKey: [`${gridScope}-grid-config`, projectId], queryFn: () => gridScope === 'sprint' ? api.sprintGridConfig(projectId) : api.gridConfig(projectId)})
  const result = direct ? issues : epics
  const changeSort = (field: SortField) => { if (sortField === field) setSortDirection(value => value === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc') } }
  const valueFor = (issue: Issue) => ({key: issue.issue_key, summary: issue.summary, type: issue.issue_type.name ?? '', baseline: issue.baseline_due_at ?? '', revised: issue.due_at ?? '', status: issue.status.name ?? ''})[sortField]
  const allItems = result.data?.items ?? []
  const issueTypes = [...new Set(allItems.map(issue => issue.issue_type.name).filter((value): value is string => Boolean(value)))].sort()
  const statuses = [...new Set(allItems.map(issue => issue.status.name).filter((value): value is string => Boolean(value)))].sort()
  const today = new Date().toISOString().slice(0, 10)
  const filteredItems = allItems.filter(issue => {
    const term = search.trim().toLocaleLowerCase()
    if (term && !`${issue.issue_key} ${issue.summary}`.toLocaleLowerCase().includes(term)) return false
    if (issueType && issue.issue_type.name !== issueType) return false
    if (status && issue.status.name !== status) return false
    if (dueFilter === 'missing' && issue.due_at) return false
    if (dueFilter === 'defined' && !issue.due_at) return false
    if (dueFilter === 'baseline-delayed' && (!issue.baseline_due_at || issue.baseline_due_at.slice(0, 10) >= today || issue.status.category_key === 'done')) return false
    if (dueFilter === 'revised-delayed' && (!issue.due_at || issue.due_at.slice(0, 10) >= today || issue.status.category_key === 'done')) return false
    return true
  })
  const sortedItems = [...filteredItems].sort((left, right) => valueFor(left).localeCompare(valueFor(right), undefined, {numeric: true}) * (sortDirection === 'asc' ? 1 : -1))
  if (result.isLoading) return <State text="Loading work items…"/>
  if (result.error) return <State text={result.error.message}/>
  const sortButton = (field: SortField, label: string) => <button className={sortField === field ? 'sorted' : ''} onClick={() => changeSort(field)}>{label}<span aria-hidden="true">{sortField === field ? sortDirection === 'asc' ? '▲' : '▼' : '↕'}</span></button>
  const filtersActive = Boolean(search || issueType || status || dueFilter)
  const clearFilters = () => { setSearch(''); setIssueType(''); setStatus(''); setDueFilter('') }
  const optionalFields = gridConfig.data?.optional_fields ?? []
  const gridTemplate = `100px minmax(260px,1fr) 120px 125px 125px 145px ${optionalFields.map(() => '150px').join(' ')}`.trim()
  return <div className="card-result-grid"><div className="result-head"><strong>{groupLabel}</strong><span>{filteredItems.length} of {result.data?.total_count ?? 0} results</span></div><div className="issue-filter-bar"><label><span>Search</span><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Key or summary…"/></label><label><span>Issue type</span><select value={issueType} onChange={event => setIssueType(event.target.value)}><option value="">All types</option>{issueTypes.map(value => <option key={value}>{value}</option>)}</select></label><label><span>Status</span><select value={status} onChange={event => setStatus(event.target.value)}><option value="">All statuses</option>{statuses.map(value => <option key={value}>{value}</option>)}</select></label><label><span>Due date</span><select value={dueFilter} onChange={event => setDueFilter(event.target.value)}><option value="">All dates</option><option value="missing">No due date</option><option value="defined">Due date defined</option><option value="baseline-delayed">Baseline delayed</option><option value="revised-delayed">Revised delayed</option></select></label><button className="secondary" disabled={!filtersActive} onClick={clearFilters}>Clear filters</button></div>{sortedItems.length ? <div className="issue-list"><div className="issue-grid-head" style={{gridTemplateColumns: gridTemplate}}>{sortButton('key', 'Key')}{sortButton('summary', 'Summary')}{sortButton('type', 'Issue type')}{sortButton('baseline', 'Baseline due')}{sortButton('revised', 'Revised due')}{sortButton('status', 'Status')}{optionalFields.map(field => <span className="optional-grid-heading" key={field.field_id}>{field.name}</span>)}</div>{sortedItems.map(issue => <div className="issue-row card-issue-row" style={{gridTemplateColumns: gridTemplate}} key={issue.jira_issue_id}><span className="issue-key-cell"><b>{issue.issue_key}</b><button className="issue-info" onClick={() => setMetadataIssueKey(issue.issue_key)} aria-label={`Show live Jira metadata for ${issue.issue_key}`} title="Show live Jira metadata">i</button></span><span>{issue.summary}</span><small>{issue.issue_type.name ?? 'Unknown type'}</small><DueDate value={issue.baseline_due_at}/><DueDate value={issue.due_at} revised/><StatusBadge name={issue.status.name} category={issue.status.category_key}/>{optionalFields.map(field => <span className="optional-grid-value" title={gridValueText(issue.configured_fields?.[field.field_id])} key={field.field_id}>{gridValueText(issue.configured_fields?.[field.field_id])}</span>)}</div>)}</div> : <State text={filtersActive ? 'No work items match the selected filters.' : 'No matching work items.'}/>} {metadataIssueKey && <IssueMetadataModal issueKey={metadataIssueKey} metadata={liveMetadata.data} loading={liveMetadata.isLoading} error={liveMetadata.error} onClose={() => setMetadataIssueKey(null)}/>}</div>
}

function gridValueText(value: unknown): string {
  if (value == null || value === '') return '—'
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value)
  if (Array.isArray(value)) return value.map(gridValueText).filter(item => item !== '—').join(', ') || '—'
  const object = value as Record<string, unknown>
  if (object.type === 'doc') return adfText(object).trim() || '—'
  for (const key of ['displayName', 'name', 'value', 'label', 'key']) if (object[key] != null) return gridValueText(object[key])
  return Object.entries(object).map(([key, nested]) => `${key}: ${gridValueText(nested)}`).join('; ')
}

function adfText(node: unknown): string {
  if (!node || typeof node !== 'object') return ''
  const item = node as {type?: string; text?: string; content?: unknown[]}
  if (item.type === 'text') return item.text ?? ''
  if (item.type === 'hardBreak') return '\n'
  const content = item.content?.map(adfText).join('') ?? ''
  if (['tableCell', 'tableHeader'].includes(item.type ?? '')) return `${content.trim()} | `
  if (item.type === 'tableRow') return `${content.replace(/\s*\|\s*$/, '')}\n`
  if (item.type === 'bulletList' || item.type === 'orderedList') return `${content}\n`
  if (item.type === 'listItem') return `• ${content.trim()}\n`
  return ['paragraph', 'heading'].includes(item.type ?? '') ? `${content}\n` : content
}

function MetadataValue({value}: {value: unknown}) {
  if (value == null || value === '') return <span className="metadata-empty">Not set</span>
  if (typeof value === 'string') return /^https?:\/\//.test(value) ? <a href={value} target="_blank" rel="noreferrer">{value}</a> : <span>{value}</span>
  if (typeof value === 'number' || typeof value === 'boolean') return <span>{String(value)}</span>
  if (Array.isArray(value)) {
    if (!value.length) return <span className="metadata-empty">None</span>
    if (value.every(item => ['string', 'number', 'boolean'].includes(typeof item))) return <div className="metadata-pills">{value.map((item, index) => <span key={`${String(item)}-${index}`}>{String(item)}</span>)}</div>
    return <div className="metadata-list">{value.map((item, index) => <div key={index}><b>{index + 1}</b><MetadataValue value={item}/></div>)}</div>
  }
  const objectValue = value as Record<string, unknown>
  if (objectValue.type === 'doc' && Array.isArray(objectValue.content)) return <div className="metadata-richtext">{adfText(objectValue).trim() || 'Not set'}</div>
  return <div className="metadata-object">{Object.entries(objectValue).map(([key, nested]) => <div key={key}><strong>{key.replaceAll('_', ' ')}</strong><MetadataValue value={nested}/></div>)}</div>
}

function IssueMetadataModal({issueKey, metadata, loading, error, onClose}: {issueKey: string; metadata?: LiveIssueMetadata; loading: boolean; error: Error | null; onClose: () => void}) {
  useEffect(() => {
    const close = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose() }
    window.addEventListener('keydown', close)
    return () => window.removeEventListener('keydown', close)
  }, [onClose])
  const rows = metadata ? Object.entries(metadata.fields).map(([fieldId, value]) => ({fieldId, name: metadata.names[fieldId] ?? fieldId, value})).sort((a, b) => a.name.localeCompare(b.name)) : []
  return <div className="metadata-modal-backdrop" onMouseDown={onClose}><section className="metadata-modal" role="dialog" aria-modal="true" aria-labelledby="metadata-title" onMouseDown={event => event.stopPropagation()}><div className="wbs-modal-head"><div><span className="step">LIVE FROM JIRA · NOT STORED</span><h2 id="metadata-title">{issueKey} metadata</h2></div><button className="wbs-modal-close" onClick={onClose} aria-label="Close Jira metadata">×</button></div>{loading ? <State text="Fetching current metadata from Jira…"/> : error ? <State text={error.message}/> : <div className="metadata-table" role="table" aria-label={`Live Jira metadata for ${issueKey}`}>{rows.map(row => <div className="metadata-row" role="row" key={row.fieldId}><div role="cell"><strong>{row.name}</strong><code>{row.fieldId}</code></div><div className="metadata-value" role="cell"><MetadataValue value={row.value}/></div></div>)}</div>}</section></div>
}

function DueDate({value, revised = false}: {value?: string | null; revised?: boolean}) {
  if (!value) return <span className="due-date missing"><i aria-hidden="true">—</i>Not set</span>
  const display = new Intl.DateTimeFormat(undefined, {day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC'}).format(new Date(value))
  return <span className={`due-date ${revised ? 'revised' : 'baseline'}`}><i aria-hidden="true">{revised ? '↻' : '◆'}</i>{display}</span>
}

function StatusBadge({name, category}: {name?: string; category?: string}) {
  const tone = category === 'done' ? 'done' : category === 'indeterminate' ? 'progress' : 'todo'
  const icon = tone === 'done' ? '✓' : tone === 'progress' ? '◔' : '○'
  return <span className={`status-badge status-${tone}`}><i aria-hidden="true">{icon}</i>{name ?? 'Unknown status'}</span>
}

function HierarchyPage({projects, fields, configured}: {projects: Project[]; fields: Field[]; configured?: boolean}) {
  const fallbackProject = projects.find(project => project.active) ?? projects[0]
  const [projectId, setProjectId] = useState('')
  useEffect(() => { if (!projectId && fallbackProject) setProjectId(fallbackProject.jira_project_id) }, [projectId, fallbackProject])
  const project = projects.find(item => item.jira_project_id === projectId)
  const config = useQuery({queryKey: ['traceability-config', projectId], queryFn: () => api.traceabilityConfig(projectId), enabled: !!projectId})
  const projectFields = useQuery({queryKey: ['hierarchy-fields', projectId], queryFn: () => api.fields('', projectId), enabled: !!projectId})
  const roots = useQuery({queryKey: ['roots', projectId], queryFn: () => api.roots(projectId), enabled: !!projectId})
  const configuredFields = config.data?.grouping_fields ?? ['labels', 'status_id', 'issue_type_id']
  const applicableFields = projectFields.data?.items ?? []
  const savedFields = fields.filter(field => configuredFields.includes(field.jira_field_id))
  const hierarchyFields = [...applicableFields, ...savedFields].filter((field, index, all) => all.findIndex(item => item.jira_field_id === field.jira_field_id) === index)
  return <><PageHeader eyebrow="WORK BREAKDOWN" title="Issue hierarchy" subtitle={project ? `${project.key} · Jira ID ${project.jira_project_id} · Parent links from Jira` : 'Select a project'} configured={configured}/><section className="project-picker"><label>Project <select aria-label="Hierarchy project" value={projectId} onChange={event => setProjectId(event.target.value)}><option value="" disabled>Select a project</option>{projects.map(item => <option key={item.jira_project_id} value={item.jira_project_id}>{item.key} · {item.name}</option>)}</select></label><span>{config.data?.persisted ? `${configuredFields.length} saved grouping levels` : 'Using default grouping'}</span></section>{projectId && !config.isLoading && !projectFields.isLoading ? <HierarchyView key={`${projectId}-${configuredFields.join('|')}`} roots={roots.data?.items ?? []} loading={roots.isLoading} fields={hierarchyFields} projectIds={[projectId]} initialFields={configuredFields}/> : <State text="Loading project grouping fields…"/>}</>
}

function TraceabilityConfiguration({projects, fields, onNotice}: {projects: Project[]; fields: Field[]; onNotice: (message: string) => void}) {
  const queryClient = useQueryClient()
  const fallbackProject = projects.find(project => project.active) ?? projects[0]
  const [projectId, setProjectId] = useState('')
  const [levels, setLevels] = useState<string[]>(['labels', 'status_id', 'issue_type_id'])
  const [captions, setCaptions] = useState<string[]>(['', '', ''])
  useEffect(() => { if (!projectId && fallbackProject) setProjectId(fallbackProject.jira_project_id) }, [projectId, fallbackProject])
  const config = useQuery({queryKey: ['traceability-config', projectId], queryFn: () => api.traceabilityConfig(projectId), enabled: !!projectId})
  useEffect(() => { if (config.data) { setLevels(config.data.grouping_fields); setCaptions(config.data.grouping_fields.map((_, index) => config.data?.level_captions[index] ?? '')) } }, [config.data])
  const save = useMutation({mutationFn: () => api.saveTraceabilityConfig(projectId, levels, captions), onSuccess: data => {queryClient.setQueryData(['traceability-config', projectId], data); onNotice(`Saved ${levels.length} traceability levels for ${projects.find(project => project.jira_project_id === projectId)?.key ?? projectId}.`)}, onError: error => onNotice(error.message)})
  const choices = groupingChoices(fields)
  const addLevel = () => { const next = choices.find(choice => !levels.includes(choice.id)); if (next) { setLevels(current => [...current, next.id]); setCaptions(current => [...current, '']) } }
  const removeLevel = (index: number) => { setLevels(current => current.filter((_, position) => position !== index)); setCaptions(current => current.filter((_, position) => position !== index)) }
  return <section className="trace-config"><div className="trace-project"><label>Project<select aria-label="Traceability project" value={projectId} onChange={event => setProjectId(event.target.value)}><option value="" disabled>Select a project</option>{projects.map(project => <option key={project.jira_project_id} value={project.jira_project_id}>{project.key} · {project.name}</option>)}</select></label><p>Configure the grouping field and the caption shown in Card view for each level.</p></div><div className="level-editor">{levels.map((field, index) => <div className="level-edit" key={index}><span>{index + 1}</span><label><span className="sr-only">Grouping field for level {index + 1}</span><select value={field} onChange={event => setLevels(current => current.map((item, position) => position === index ? event.target.value : item))}>{choices.map(choice => <option key={choice.id} value={choice.id}>{choice.name}</option>)}</select></label><label className="caption-input"><span>Card caption</span><input maxLength={100} value={captions[index] ?? ''} placeholder={choices.find(choice => choice.id === field)?.name ?? field} onChange={event => setCaptions(current => current.map((item, position) => position === index ? event.target.value : item))}/></label>{levels.length > 1 && <button className="secondary" aria-label={`Remove level ${index + 1}`} onClick={() => removeLevel(index)}>Remove</button>}</div>)}</div><div className="trace-actions"><button className="secondary" disabled={levels.length >= choices.length} onClick={addLevel}>Add grouping level</button><button disabled={!projectId || save.isPending} onClick={() => save.mutate()}>{save.isPending ? 'Saving…' : 'Save configuration'}</button></div></section>
}

function HierarchyView({roots, loading, fields, projectIds, initialFields}: {roots: Issue[]; loading: boolean; fields: Field[]; projectIds: string[]; initialFields: string[]}) {
  const choices = groupingChoices(fields)
  const [groupFields, setGroupFields] = useState(initialFields)
  const [selectedGroups, setSelectedGroups] = useState<Array<{value: unknown; label: string} | null>>(() => initialFields.map(() => null))
  const levelFilters = selectedGroups.map((group, index) => group ? groupFilter(groupFields[index], group) : null)
  const filtersBeforeLevel = groupFields.map((_, index) => combineFilters(levelFilters.slice(0, index)))
  const finalFilter = combineFilters(selectedGroups.map((group, index) => group ? groupFilter(groupFields[index], group) : null))
  const groupQueries = useQueries({queries: groupFields.map((field, index) => ({queryKey: ['hierarchy-groups', index, field, filtersBeforeLevel[index], projectIds], queryFn: () => api.groupBy(field, projectIds, filtersBeforeLevel[index] ?? undefined), enabled: projectIds.length > 0 && (index === 0 || !!selectedGroups[index - 1])}))})
  const deepestLevel = selectedGroups.reduce((last, group, index) => group ? index : last, -1)
  const showDirectIssueType = deepestLevel >= 0 && groupFields[deepestLevel] === 'issue_type_id'
  const epicMatches = useQuery({queryKey: ['group-epics', finalFilter, projectIds], queryFn: () => api.epicsByFilter(projectIds, finalFilter!), enabled: !!finalFilter && !showDirectIssueType && projectIds.length > 0})
  const directMatches = useQuery({queryKey: ['group-direct-items', finalFilter, projectIds], queryFn: () => api.issuesByFilter(projectIds, finalFilter!), enabled: !!finalFilter && showDirectIssueType && projectIds.length > 0})
  const matches = showDirectIssueType ? directMatches : epicMatches
  const changeField = (level: number, value: string) => { setGroupFields(current => current.map((field, index) => index === level ? value : field)); setSelectedGroups(current => current.map((group, index) => index >= level ? null : group)) }
  const selectGroup = (level: number, group: {value: unknown; label: string}) => setSelectedGroups(current => current.map((selected, index) => index === level ? group : index > level ? null : selected))
  return <>
    <section className="grouping-card"><div className="cardhead"><div><span className="step">{groupFields.length}-LEVEL GROUPING</span><h2>Drill down through Jira fields</h2></div><span>{groupFields.map(field => choices.find(choice => choice.id === field)?.name ?? field).join(' → ')}</span></div>
      {groupFields.map((field, index) => <GroupingLevel key={`${index}-${field}`} level={index} field={field} choices={choices} selected={selectedGroups[index]} query={groupQueries[index]} enabled={index === 0 || !!selectedGroups[index - 1]} onFieldChange={changeField} onSelect={selectGroup}/>)}
      {finalFilter && <div className="group-results"><div className="result-head"><strong>{selectedGroups.filter(Boolean).map(group => group?.label).join(' / ')}</strong><span>{matches.data ? showDirectIssueType ? `${matches.data.total_count} matching ${selectedGroups[deepestLevel]?.label ?? 'work items'}` : `${matches.data.total_count} epics · ${'matching_work_item_count' in matches.data ? matches.data.matching_work_item_count : matches.data.total_count} matching work items` : 'Loading results…'}</span></div>{matches.isLoading ? <State text={showDirectIssueType ? 'Loading matching work items…' : 'Finding epic ancestors…'}/> : matches.data?.items.length ? <div className="group-epics">{matches.data.items.map(issue => <TreeNode key={issue.jira_issue_id} issue={issue} depth={0}/>)}</div> : <State text="No matching work items were found for this grouping."/>}</div>}
    </section>
    <section className="hierarchy-card"><div className="cardhead"><div><span className="step">EXPANDABLE TREE</span><h2>Roots and descendants</h2></div><span>{roots.length} loaded roots</span></div>{loading ? <State text="Loading hierarchy…"/> : roots.length ? <div className="tree">{roots.map(issue => <TreeNode key={issue.jira_issue_id} issue={issue} depth={0}/>)}</div> : <State text="Run a full sync to populate the hierarchy."/>}</section>
  </>
}

type Group = {value: unknown; label: string; issue_count: number; task_count?: number; in_progress_count?: number; delayed_count?: number; next_group_count?: number}
type GroupQuery = {data?: {groups: Group[]; non_additive: boolean}; isLoading: boolean; error: Error | null}

function groupFilter(fieldId: string, group: {value: unknown}) { return {field_id: fieldId, operator: group.value == null ? 'is_null' : 'eq', value: group.value == null ? true : group.value} }
function combineFilters(filters: Array<Record<string, unknown> | null>) { const active = filters.filter((filter): filter is Record<string, unknown> => !!filter); return active.length === 0 ? null : active.length === 1 ? active[0] : {and: active} }

function GroupingLevel({level, field, choices, selected, query, enabled, onFieldChange, onSelect}: {level: number; field: string; choices: {id: string; name: string}[]; selected: {value: unknown; label: string} | null; query: GroupQuery; enabled: boolean; onFieldChange: (level: number, value: string) => void; onSelect: (level: number, group: Group) => void}) {
  return <div className={`group-level ${enabled ? '' : 'disabled'}`}><div className="group-level-head"><strong>Level {level + 1}</strong><label className="group-select">Group by <select aria-label={`Grouping level ${level + 1}`} value={field} disabled={!enabled} onChange={event => onFieldChange(level, event.target.value)}>{choices.map(choice => <option key={choice.id} value={choice.id}>{choice.name}</option>)}</select></label></div>{!enabled ? <p>Select a value in Level {level} to continue.</p> : query.isLoading ? <State text="Building groups…"/> : query.error ? <State text={query.error.message}/> : <div className="group-chips">{query.data?.groups.map(group => <button key={`${field}-${String(group.value)}`} className={selected?.value === group.value ? 'group-chip selected' : 'group-chip'} onClick={() => onSelect(level, group)}><span>{group.label}</span><strong>{group.issue_count}</strong></button>)}</div>}{query.data?.non_additive && enabled && <p className="group-warning">Multi-value groups can overlap.</p>}</div>
}

function TreeNode({issue, depth}: {issue: Issue; depth: number}) { const [expanded, setExpanded] = useState(false); const children = useQuery({queryKey: ['children', issue.jira_issue_id], queryFn: () => api.children(issue.jira_issue_id), enabled: expanded}); return <div className="tree-branch"><button className="tree-row" style={{paddingLeft: 18 + depth * 24}} onClick={() => setExpanded(value => !value)} aria-expanded={expanded}><span className="chevron">{expanded ? '−' : '+'}</span><b>{issue.issue_key}</b><span>{issue.summary}</span><small>{issue.issue_type.name ?? 'Unknown type'} · {issue.status.name ?? 'Unknown status'}</small></button>{expanded && (children.isLoading ? <div className="tree-loading">Loading children…</div> : children.data?.items.length ? children.data.items.map(child => <TreeNode key={child.jira_issue_id} issue={child} depth={depth + 1}/>) : <div className="tree-empty" style={{paddingLeft: 54 + depth * 24}}>No direct children</div>)}</div> }

function Metric({label, value}: {label: string; value: string | number}) { return <div className="metric"><small>{label}</small><strong>{value}</strong></div> }

function fieldType(field: Field) { return String(field.schema_json.type ?? field.schema_json.custom ?? 'unknown type') }
function State({text}: {text: string}) { return <div className="state">{text}</div> }
function GrafanaWbsDocument() {
  return <section className="grafana-guide grafana-endpoint-guide"><section className="grafana-schema"><div><span className="step">TWO PROJECT EXPORTS</span><h2>Use one endpoint for each application view</h2></div><div className="grafana-schema-grid"><article><strong>Traceability Card View</strong><p><code>GET /api/v1/integrations/grafana/traceability/cards/{'{project_id}'}</code></p><p>Returns nested and flat cards, all delivery calculations, grid configuration, bottom-level work items, configured fields, nodes and edges.</p></article><article><strong>WBS Flow</strong><p><code>GET /api/v1/integrations/grafana/wbs/{'{project_id}'}</code></p><p>Returns the exact configured WBS levels, compacted flow nodes, links, issue totals and Grafana Node graph frames.</p></article><article><strong>Required input</strong><p>Replace <code>{'{project_id}'}</code> with the Jira project ID. No level, field, caption or calculation parameters are required.</p></article></div></section><section className="api-example"><span className="step">PROJECT 10732 EXAMPLES</span><h2>Card View and WBS Flow</h2><pre>{`# Complete Traceability Card View
curl "http://localhost:8000/api/v1/integrations/grafana/traceability/cards/10732"

# WBS Flow
curl "http://localhost:8000/api/v1/integrations/grafana/wbs/10732"`}</pre><p>Both responses resolve their level fields and captions from the same saved Traceability Level Config. The Card View additionally resolves the saved Traceability Grid Config.</p></section></section>
}
